// Teoribok: Statikk og dynamikk (MAPE1300 enhet 1-3), Fasthetslære (FAST), Maskinkonstruksjon (MATS1600),
// Svingninger (SVING), Elementmetoden (FEM)

// ================= MAPE1300 – enhet 1: Fagverk og friksjon =================
TOPICS("MAPE1300", 1, [
{ id: "knutepunktmetoden",
  fig: `<svg viewBox="0 0 240 140"><circle cx="130" cy="70" r="4" class="d"/><path d="M130 70H30" class="d"/><path d="M130 70L205 25" class="d"/><path d="M130 70V125" class="a"/><path d="M130 125l-6-12h12z" class="af"/><path d="M95 70l-15 4 4-15z" class="af"/><text x="55" y="62">S<tspan dy="4" font-size="10">1</tspan></text><path d="M162 52l15-9-2 17z" class="af"/><text x="161" y="33">S<tspan dy="4" font-size="10">2</tspan></text><text x="138" y="111">P</text></svg>`,
  nb: { t: "Knutepunktmetoden",
    intro: "I et fagverk er hver stav et to-kraft-element: kraften virker langs staven, enten i strekk eller trykk. Knutepunktmetoden isolerer ett knutepunkt om gangen og bruker likevekt der. Med bare to likevektsligninger i planet kan du løse maks to ukjente stavkrefter per knutepunkt.",
    f: [["\\sum F_x = 0,\\ \\sum F_y = 0", "likevekt i knutepunktet, maks 2 ukjente"]],
    legend: [["S", "stavkraft (positiv = strekk)", "N"]],
    ex: "Anta strekk i alle staver. Får du $S_1 = -8$ kN?\nDa er staven i trykk med 8 kN, ikke feilregnet.",
    tip: "Start i et knutepunkt med maks to ukjente staver, og la fortegnet fortelle om det ble trykk." },
  en: { t: "Method of joints",
    intro: "In a truss each member is a two-force member: the force acts along the member, either in tension or compression. The method of joints isolates one joint at a time and applies equilibrium there. With only two equilibrium equations in the plane, you can solve at most two unknown member forces per joint.",
    f: [["\\sum F_x = 0,\\ \\sum F_y = 0", "equilibrium at the joint, at most 2 unknowns"]],
    legend: [["S", "member force (positive = tension)", "N"]],
    ex: "Assume tension in every member. If you get $S_1 = -8$ kN,\nthe member is in compression with 8 kN, not a mistake.",
    tip: "Start at a joint with at most two unknown members, and let the sign tell you when it becomes compression." } },
{ id: "snittmetoden",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 100H220" class="dim"/><path d="M50 100L110 40H180L220 100" class="b"/><path d="M110 40L20 100 M180 40L220 100" class="dash"/><path d="M20 118V90M20 118l-8-4M20 118l8-4" class="g"/><path d="M215 40l14 8-4 14z" class="af"/><path d="M215 40H90" class="a"/><text x="150" y="35">P</text><text x="30" y="112">A</text></svg>`,
  nb: { t: "Snittmetoden",
    intro: "Snittmetoden tar for seg en hel del av fagverket på én gang i stedet for ett knutepunkt. Du snitter gjennom maks tre staver, fjerner den ene delen og setter inn stavkreftene som ytre krefter. Da kan du bruke alle tre likevektsligningene, inkludert moment, på den gjenværende delen.",
    f: [["\\sum F_x = 0,\\ \\sum F_y = 0,\\ \\sum M = 0", "likevekt for den snittede delen"]],
    legend: [["S", "stavkraft i snittet stav", "N"]],
    ex: "Snitt gjennom tre staver i et fagverk med kjent last $P$.\nTa moment om punktet der to av de ukjente stavene møtes – da gjenstår bare én ukjent.",
    tip: "Velg momentpunkt der to av de tre ukjente stavene skjærer hverandre, så forsvinner de fra ligningen." },
  en: { t: "Method of sections",
    intro: "The method of sections treats a whole part of the truss at once instead of one joint. You cut through at most three members, remove one part and put the member forces in as external forces. Then you can use all three equilibrium equations, including moment, on the remaining part.",
    f: [["\\sum F_x = 0,\\ \\sum F_y = 0,\\ \\sum M = 0", "equilibrium for the cut part"]],
    legend: [["S", "force in the cut member", "N"]],
    ex: "Cut through three members in a truss with a known load $P$.\nTake moments about the point where two of the unknown members meet – then only one unknown remains.",
    tip: "Choose the moment point where two of the three unknown members intersect, so they drop out of the equation." } },
{ id: "friksjon",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 120L220 60" class="d"/><rect x="0" y="0" width="0" height="0"/><path d="M110 92L150 79L157 101L117 114Z" class="b"/><path d="M134 96L134 40" class="a"/><path d="M134 40l-6 12h12z" class="af"/><path d="M134 96L104 106" class="g"/><path d="M104 106l4-12 10 6z" class="gf"/><path d="M134 96L174 84" class="r"/><path d="M174 84l-12 -3 5 -11z" class="rf"/><text x="140" y="35">W</text><text x="83" y="117">N</text><text x="178" y="90">F</text></svg>`,
  nb: { t: "Friksjon",
    intro: "Friksjon er en reaksjonskraft langs kontaktflaten som motvirker glidning. Statisk friksjon er ikke fast, men akkurat så stor som likevekten krever, opp til en grense $\\mu_s N$. Når kroppen glir, er friksjonen kinetisk og som regel litt lavere.",
    f: [["F \\le \\mu_s N", "statisk friksjon (før glidning)"], ["F = \\mu_k N", "kinetisk friksjon (under glidning)"]],
    legend: [["F", "friksjonskraft", "N"], ["N", "normalkraft", "N"], ["\\mu_s,\\ \\mu_k", "statisk/kinetisk friksjonskoeffisient", ""]],
    ex: "Kloss på 10 kg, $\\mu_s = 0{,}4$, ligger i ro på flatt underlag:\n$F_{maks} = \\mu_s N = 0{,}4\\cdot 10\\cdot 9{,}81 \\approx 39{,}2$ N.",
    tip: "Finn alltid $N$ fra likevekt vinkelrett på flaten – den er ikke alltid lik tyngden." },
  en: { t: "Friction",
    intro: "Friction is a reaction force along the contact surface that resists sliding. Static friction is not fixed but exactly as large as equilibrium requires, up to a limit $\\mu_s N$. Once the body slides, friction is kinetic and usually a bit lower.",
    f: [["F \\le \\mu_s N", "static friction (before sliding)"], ["F = \\mu_k N", "kinetic friction (while sliding)"]],
    legend: [["F", "friction force", "N"], ["N", "normal force", "N"], ["\\mu_s,\\ \\mu_k", "static/kinetic friction coefficient", ""]],
    ex: "A 10 kg block, $\\mu_s = 0.4$, resting on a flat surface:\n$F_{max} = \\mu_s N = 0.4\\cdot 10\\cdot 9.81 \\approx 39.2$ N.",
    tip: "Always find $N$ from equilibrium perpendicular to the surface – it is not always equal to the weight." } },
{ id: "tyngdepunkt",
  fig: `<svg viewBox="0 0 240 140"><path d="M40 115H210" class="dim"/><path d="M40 115L125 25L210 115Z" class="d"/><path d="M125 115V25" class="dash"/><circle cx="125" cy="88" r="4" class="d"/><path d="M100 115V128M100 115l-6 13h12z" class="dim"/><path d="M150 115V128M150 115l-6 13h12z" class="dim"/><text x="130" y="108">C</text><text x="117" y="65">h</text></svg>`,
  nb: { t: "Tyngdepunkt",
    intro: "Tyngdepunktet er punktet der hele tyngden av et legeme kan tenkes å angripe. For sammensatte flater finner du det ved å veie hvert delareal med sin egen posisjon. Kjente formfigurer, som trekanten, har standardplassering av tyngdepunktet som er greit å huske.",
    f: [["\\bar x = \\dfrac{\\sum A_i x_i}{\\sum A_i}", "tyngdepunkt for sammensatt flate"], ["y_C = h/3", "trekant, målt fra grunnlinjen"]],
    legend: [["A_i", "delareal $i$", "m²"], ["x_i", "tyngdepunkt for delareal $i$", "m"], ["h", "trekantens høyde", "m"]],
    ex: "Trekant med høyde $h = 0{,}9$ m:\n$y_C = h/3 = 0{,}3$ m fra grunnlinjen.",
    tip: "Tyngdepunktet i en trekant ligger en tredjedel av høyden over grunnlinjen, der medianene møtes." },
  en: { t: "Centroid",
    intro: "The centroid is the point where the whole weight of a body can be thought to act. For composite areas you find it by weighting each part area with its own position. Common shapes, such as the triangle, have a standard centroid location worth remembering.",
    f: [["\\bar x = \\dfrac{\\sum A_i x_i}{\\sum A_i}", "centroid of a composite area"], ["y_C = h/3", "triangle, measured from the base"]],
    legend: [["A_i", "part area $i$", "m²"], ["x_i", "centroid of part area $i$", "m"], ["h", "height of the triangle", "m"]],
    ex: "A triangle with height $h = 0.9$ m:\n$y_C = h/3 = 0.3$ m from the base.",
    tip: "The centroid of a triangle lies one third of the height above the base, where the medians meet." } }
]);

// ================= MAPE1300 – enhet 2: Dynamikk =================
TOPICS("MAPE1300", 2, [
{ id: "kinematikk",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 115H220" class="dim"/><path d="M30 115V20" class="dim"/><path d="M30 100Q120 100 210 35" class="a"/><text x="10" y="60">s</text><text x="120" y="130">t</text><text x="148" y="57">v</text></svg>`,
  nb: { t: "Kinematikk",
    intro: "Kinematikk beskriver bevegelsen uten å se på kreftene som forårsaker den: posisjon, fart og akselerasjon. Med konstant akselerasjon, for eksempel fritt fall eller jevn bremsing, gjelder tre enkle formler som kobler sammen fart, tid og strekning.",
    f: [["v = v_0 + at", "fart som funksjon av tid"], ["s = v_0t + \\tfrac12at^2", "strekning som funksjon av tid"], ["v^2 = v_0^2 + 2as", "fart uten tid"]],
    legend: [["v_0,\\ v", "start-/sluttfart", "m/s"], ["a", "akselerasjon (konstant)", "m/s²"], ["s", "tilbakelagt strekning", "m"]],
    ex: "Bil fra 0 til 20 m/s på 5 s, konstant $a$:\n$a = (20-0)/5 = 4$ m/s².",
    tip: "Formlene over gjelder bare når akselerasjonen er konstant." },
  en: { t: "Kinematics",
    intro: "Kinematics describes the motion itself without looking at the forces that cause it: position, velocity and acceleration. With constant acceleration, for example free fall or uniform braking, three simple formulas connect speed, time and distance.",
    f: [["v = v_0 + at", "velocity as a function of time"], ["s = v_0t + \\tfrac12at^2", "distance as a function of time"], ["v^2 = v_0^2 + 2as", "velocity without time"]],
    legend: [["v_0,\\ v", "initial/final velocity", "m/s"], ["a", "acceleration (constant)", "m/s²"], ["s", "distance travelled", "m"]],
    ex: "A car from 0 to 20 m/s in 5 s, constant $a$:\n$a = (20-0)/5 = 4$ m/s².",
    tip: "The formulas above only hold when the acceleration is constant." } },
{ id: "newtons-2-lov",
  fig: `<svg viewBox="0 0 240 140"><rect x="90" y="60" width="60" height="40" class="b"/><path d="M150 80H210" class="a"/><path d="M210 80l-14-6v12z" class="af"/><path d="M90 80H35" class="dash"/><text x="215" y="76">F</text><text x="30" y="76">f</text><path d="M120 60V15" class="dim"/><text x="105" y="30">a</text></svg>`,
  nb: { t: "Newtons 2. lov",
    intro: "Newtons 2. lov kobler kreftene som virker på et legeme til akselerasjonen det får. Summen av alle kreftene, funnet fra et frilegemediagram, er lik masse ganger akselerasjon. Loven gjelder i hver retning for seg.",
    f: [["\\sum F = ma", "Newtons 2. lov"]],
    legend: [["F", "kraft", "N"], ["m", "masse", "kg"], ["a", "akselerasjon", "m/s²"]],
    ex: "Kloss på 5 kg dras med 30 N, friksjon 10 N mot:\n$a = (30-10)/5 = 4$ m/s².",
    tip: "Konstant fart betyr $\\sum F = 0$, ikke at det trengs en kraft for å holde farten oppe." },
  en: { t: "Newton's second law",
    intro: "Newton's second law links the forces acting on a body to the acceleration it gets. The sum of all forces, found from a free-body diagram, equals mass times acceleration. The law applies in each direction separately.",
    f: [["\\sum F = ma", "Newton's second law"]],
    legend: [["F", "force", "N"], ["m", "mass", "kg"], ["a", "acceleration", "m/s²"]],
    ex: "A 5 kg block is pulled with 30 N, with 10 N friction against it:\n$a = (30-10)/5 = 4$ m/s².",
    tip: "Constant speed means $\\sum F = 0$, not that a force is needed to keep the speed up." } },
{ id: "arbeid-energi",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 115H210" class="dim"/><circle cx="60" cy="95" r="10" class="d"/><circle cx="170" cy="60" r="10" class="d"/><path d="M60 115V20L170 20V60" class="dash"/><text x="35" y="40">h</text><text x="66" y="84">E<tspan dy="4" font-size="10">k1</tspan></text><text x="148" y="51">E<tspan dy="4" font-size="10">k2</tspan></text></svg>`,
  nb: { t: "Arbeid og energi",
    intro: "Arbeid–energi-metoden er raskest når du vil finne farten etter en strekning uten å regne akselerasjon underveis. Kinetisk og potensiell energi omdannes til hverandre, mens friksjon og motorer tilfører eller fjerner energi som arbeid.",
    f: [["E_k = \\tfrac12mv^2", "kinetisk energi"], ["E_{k1} + E_{p1} + W_{andre} = E_{k2} + E_{p2}", "arbeid–energi-teoremet"]],
    legend: [["E_k,\\ E_p", "kinetisk/potensiell energi", "J"], ["W_{andre}", "arbeid fra friksjon m.m.", "J"]],
    ex: "Fall fra $h = 5$ m, ingen luftmotstand:\n$mgh = \\tfrac12mv^2 \\Rightarrow v = \\sqrt{2\\cdot 9{,}81\\cdot 5} \\approx 9{,}9$ m/s.",
    tip: "Friksjon gir negativt arbeid – trekk det fra energien i stedet for å legge det til." },
  en: { t: "Work and energy",
    intro: "The work–energy method is fastest when you want the speed after a distance without tracking the acceleration along the way. Kinetic and potential energy convert into each other, while friction and motors add or remove energy as work.",
    f: [["E_k = \\tfrac12mv^2", "kinetic energy"], ["E_{k1} + E_{p1} + W_{other} = E_{k2} + E_{p2}", "the work–energy theorem"]],
    legend: [["E_k,\\ E_p", "kinetic/potential energy", "J"], ["W_{other}", "work from friction etc.", "J"]],
    ex: "A fall from $h = 5$ m, no air resistance:\n$mgh = \\tfrac12mv^2 \\Rightarrow v = \\sqrt{2\\cdot 9.81\\cdot 5} \\approx 9.9$ m/s.",
    tip: "Friction does negative work – subtract it from the energy instead of adding it." } },
{ id: "bevegelsesmengde",
  fig: `<svg viewBox="0 0 240 140"><circle cx="60" cy="70" r="14" class="d"/><circle cx="180" cy="70" r="10" class="d"/><path d="M20 70H45" class="a"/><path d="M45 70l-10-5v10z" class="af"/><path d="M120 70H160" class="dash"/><path d="M60 70H80" class="a"/><path d="M80 70l10-5v10z" class="af"/><text x="20" y="50">v<tspan dy="4" font-size="10">1</tspan></text><text x="165" y="50">v'</text></svg>`,
  nb: { t: "Bevegelsesmengde og støt",
    intro: "Bevegelsesmengde er masse ganger fart, og impulsloven kobler den til kraften over tid. I et støt uten ytre horisontale krefter er bevegelsesmengden bevart, selv om kinetisk energi kan gå tapt til varme og deformasjon.",
    f: [["\\int F\\,dt = \\Delta(mv)", "impulsloven"], ["v' = \\dfrac{m_1v_1 + m_2v_2}{m_1+m_2}", "felles fart etter fullstendig uelastisk støt"]],
    legend: [["p = mv", "bevegelsesmengde", "kg m/s"], ["v'", "felles fart etter støtet", "m/s"]],
    ex: "Vogn på 4 kg med 6 m/s treffer en vogn på 2 kg i ro, henger sammen:\n$v' = (4\\cdot 6 + 0)/6 = 4$ m/s.",
    tip: "Bare bevegelsesmengden er bevart i et uelastisk støt – ikke kinetisk energi." },
  en: { t: "Momentum and impact",
    intro: "Momentum is mass times velocity, and the impulse–momentum principle links it to force over time. In an impact with no external horizontal forces, momentum is conserved, even though kinetic energy can be lost to heat and deformation.",
    f: [["\\int F\\,dt = \\Delta(mv)", "the impulse–momentum principle"], ["v' = \\dfrac{m_1v_1 + m_2v_2}{m_1+m_2}", "common velocity after a perfectly inelastic impact"]],
    legend: [["p = mv", "momentum", "kg m/s"], ["v'", "common velocity after impact", "m/s"]],
    ex: "A 4 kg cart at 6 m/s hits a 2 kg cart at rest and they stick:\n$v' = (4\\cdot 6 + 0)/6 = 4$ m/s.",
    tip: "Only momentum is conserved in an inelastic impact – not kinetic energy." } }
]);

// ================= MAPE1300 – enhet 3: Bøyning av bjelker =================
TOPICS("MAPE1300", 3, [
{ id: "skjaer-moment",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 60H210" class="b"/><path d="M30 60l-10 18h20z M180 60l-10 18h20z" class="d"/><path d="M120 20V52" class="a"/><path d="M120 60l-6-13h12z" class="af"/><path d="M30 100Q120 130 210 100" class="t"/><text x="117" y="30">P</text><text x="115" y="122">M</text></svg>`,
  nb: { t: "Skjærkraft og moment",
    intro: "Skjærkraften $V$ og bøyemomentet $M$ varierer langs en bjelke og henger sammen: momentet er arealet under skjærdiagrammet. Der skjærkraften skifter fortegn (eller er null), har momentet en ekstremverdi. Diagrammene viser hvor bjelken er mest utsatt.",
    f: [["\\dfrac{dM}{dx} = V", "sammenheng mellom skjær og moment"]],
    legend: [["V", "skjærkraft", "N"], ["M", "bøyemoment", "Nm"], ["x", "posisjon langs bjelken", "m"]],
    ex: "Skjærkraften skifter fortegn midt under en punktlast.\nDer er bøyemomentet størst.",
    tip: "Finn momentets maksimum der skjærkraftdiagrammet krysser null." },
  en: { t: "Shear and moment",
    intro: "The shear force $V$ and the bending moment $M$ vary along a beam and are linked: the moment is the area under the shear diagram. Where the shear force changes sign (or is zero), the moment has an extreme value. The diagrams show where the beam is most stressed.",
    f: [["\\dfrac{dM}{dx} = V", "relation between shear and moment"]],
    legend: [["V", "shear force", "N"], ["M", "bending moment", "Nm"], ["x", "position along the beam", "m"]],
    ex: "The shear force changes sign right under a point load.\nThat is where the bending moment is largest.",
    tip: "Find the moment maximum where the shear force diagram crosses zero." } },
{ id: "maks-moment",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 60H210" class="b"/><path d="M30 60l-10 18h20z M180 60l-10 18h20z" class="d"/><path d="M30 40H210" class="a"/><path d="M30 40l0 10M60 40l0 10M90 40l0 10M120 40l0 10M150 40l0 10M180 40l0 10M210 40l0 10" class="d"/><text x="110" y="30">q</text><text x="115" y="120">L</text><path d="M30 118H210M30 112v12M210 112v12" class="dim"/></svg>`,
  nb: { t: "Maksimalt moment",
    intro: "For standard lastilfeller finnes ferdige formler for maksimalt bøyemoment, så du slipper å tegne fullt diagram hver gang. Fritt opplagt bjelke med jevnt fordelt last har maks moment midt på, mens en utkraget bjelke har det ved innspenningen.",
    f: [["M_{maks} = \\dfrac{qL^2}{8}", "fritt opplagt, jevnt fordelt last"], ["M_{maks} = \\dfrac{PL}{4}", "fritt opplagt, punktlast midt på"]],
    legend: [["q", "jevnt fordelt last", "N/m"], ["P", "punktlast", "N"], ["L", "spennvidde", "m"]],
    ex: "Bjelke på 6 m med $q = 4$ kN/m:\n$M_{maks} = 4\\cdot 6^2/8 = 18$ kNm.",
    tip: "Sjekk om lasten er punktlast eller jevnt fordelt – formlene er forskjellige." },
  en: { t: "Maximum moment",
    intro: "For standard load cases there are ready-made formulas for the maximum bending moment, so you avoid drawing the full diagram every time. A simply supported beam with a uniformly distributed load has its maximum moment at midspan, while a cantilever has it at the fixed end.",
    f: [["M_{max} = \\dfrac{qL^2}{8}", "simply supported, uniformly distributed load"], ["M_{max} = \\dfrac{PL}{4}", "simply supported, point load at midspan"]],
    legend: [["q", "uniformly distributed load", "N/m"], ["P", "point load", "N"], ["L", "span", "m"]],
    ex: "A 6 m beam with $q = 4$ kN/m:\n$M_{max} = 4\\cdot 6^2/8 = 18$ kNm.",
    tip: "Check whether the load is a point load or distributed – the formulas differ." } },
{ id: "nedboyning",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 60H210" class="dim"/><path d="M30 60l-10 18h20z M180 60l-10 18h20z" class="d"/><path d="M30 60Q120 105 210 60" class="b"/><path d="M120 60V95" class="dash"/><text x="126" y="76">δ</text><path d="M120 30V52" class="a"/><path d="M120 60l-6-13h12z" class="af"/><text x="128" y="25">P</text></svg>`,
  nb: { t: "Nedbøyning",
    intro: "Nedbøyningen er hvor mye bjelken bøyer seg under last. Den avhenger sterkt av lengden ($L^3$) og av tverrsnittets stivhet $EI$: en dobbelt så lang bjelke bøyer seg åtte ganger så mye. Store $I$-verdier, som i I-profiler, holder nedbøyningen liten.",
    f: [["\\delta = \\dfrac{PL^3}{48EI}", "fritt opplagt bjelke, punktlast midt på"]],
    legend: [["\\delta", "nedbøyning", "m"], ["E", "elastisitetsmodul", "Pa"], ["I", "arealtreghetsmoment", "m⁴"]],
    ex: "Dobler du $L$, blir $\\delta$ 8 ganger så stor,\nfordi $\\delta \\propto L^3$ og alt annet er uendret.",
    tip: "Nedbøyning er svært lengdefølsom – halver spennvidden for å redusere den mest." },
  en: { t: "Deflection",
    intro: "Deflection is how much the beam bends under load. It depends strongly on the length ($L^3$) and on the section stiffness $EI$: a beam twice as long deflects eight times as much. Large $I$ values, as in I-beams, keep the deflection small.",
    f: [["\\delta = \\dfrac{PL^3}{48EI}", "simply supported beam, point load at midspan"]],
    legend: [["\\delta", "deflection", "m"], ["E", "modulus of elasticity", "Pa"], ["I", "second moment of area", "m⁴"]],
    ex: "Doubling $L$ makes $\\delta$ 8 times as large,\nbecause $\\delta \\propto L^3$ and everything else is unchanged.",
    tip: "Deflection is very length-sensitive – halving the span reduces it the most." } },
{ id: "i-profil",
  fig: `<svg viewBox="0 0 240 140"><path d="M70 25H170V45H130V95H170V115H70V95H110V45H70Z" class="fill"/><path d="M120 25V115" class="dash"/><text x="54" y="20">b</text><text x="180" y="70">h</text></svg>`,
  nb: { t: "Tverrsnitt og I-profil",
    intro: "Bøyespenningen $\\sigma = My/I$ avhenger av arealtreghetsmomentet $I$, som vokser raskt med avstand fra nøytralaksen. Et I-profil legger mesteparten av materialet i flensene, langt fra midten, og gir dermed stor $I$ per kilo sammenlignet med et massivt rektangel.",
    f: [["I_{rekt} = \\dfrac{bh^3}{12}", "arealtreghetsmoment for et rektangel"]],
    legend: [["b", "bredde", "m"], ["h", "høyde", "m"], ["I", "arealtreghetsmoment", "m⁴"]],
    ex: "Rektangel $b = 50$ mm, $h = 100$ mm:\n$I = 50\\cdot 100^3/12 \\approx 4{,}17\\cdot10^6$ mm⁴.",
    tip: "Materiale langt fra nøytralaksen teller mest – derfor er I-profiler så effektive i bøyning." },
  en: { t: "Cross-section and I-beam",
    intro: "The bending stress $\\sigma = My/I$ depends on the second moment of area $I$, which grows quickly with distance from the neutral axis. An I-beam puts most of its material in the flanges, far from the middle, giving a large $I$ per kilogram compared with a solid rectangle.",
    f: [["I_{rect} = \\dfrac{bh^3}{12}", "second moment of area of a rectangle"]],
    legend: [["b", "width", "m"], ["h", "height", "m"], ["I", "second moment of area", "m⁴"]],
    ex: "A rectangle with $b = 50$ mm, $h = 100$ mm:\n$I = 50\\cdot 100^3/12 \\approx 4.17\\cdot10^6$ mm⁴.",
    tip: "Material far from the neutral axis counts the most – that is why I-beams are so efficient in bending." } }
]);

// ================= FAST – enhet 0: Spenning og tøyning =================
TOPICS("FAST", 0, [
{ id: "spenning-toyning",
  fig: `<svg viewBox="0 0 240 140"><rect x="70" y="45" width="60" height="50" class="fill"/><path d="M130 70H200" class="a"/><path d="M200 70l-14-6v12z" class="af"/><path d="M70 70H15" class="a"/><path d="M15 70l14-6v12z" class="af"/><path d="M70 110H130" class="dim"/><path d="M70 110v10M130 110v10" class="dim"/><text x="90" y="130">L</text><text x="205" y="66">F</text></svg>`,
  nb: { t: "Spenning og tøyning",
    intro: "Spenning er kraft per areal, og tøyning er relativ lengdeendring. Hookes lov sier at de to er proporsjonale for et elastisk materiale, med elastisitetsmodulen $E$ som forholdstall. Dette er grunnlaget for nesten all dimensjonering.",
    f: [["\\sigma = F/A", "normalspenning"], ["\\varepsilon = \\Delta L/L", "tøyning"], ["\\sigma = E\\varepsilon", "Hookes lov"]],
    legend: [["\\sigma", "normalspenning", "Pa"], ["F", "aksialkraft", "N"], ["A", "tverrsnittsareal", "m²"], ["E", "elastisitetsmodul", "Pa"]],
    ex: "Stav med $A = 100$ mm², $F = 10$ kN strekk:\n$\\sigma = 10\\,000/100 = 100$ N/mm² $= 100$ MPa.",
    tip: "Hookes lov gjelder bare under flytegrensen – deretter er sammenhengen ikke lenger lineær." },
  en: { t: "Stress and strain",
    intro: "Stress is force per area, and strain is the relative change in length. Hooke's law states that the two are proportional for an elastic material, with the modulus of elasticity $E$ as the ratio. This is the basis of almost all sizing calculations.",
    f: [["\\sigma = F/A", "normal stress"], ["\\varepsilon = \\Delta L/L", "strain"], ["\\sigma = E\\varepsilon", "Hooke's law"]],
    legend: [["\\sigma", "normal stress", "Pa"], ["F", "axial force", "N"], ["A", "cross-sectional area", "m²"], ["E", "modulus of elasticity", "Pa"]],
    ex: "A bar with $A = 100$ mm², $F = 10$ kN in tension:\n$\\sigma = 10\\,000/100 = 100$ N/mm² $= 100$ MPa.",
    tip: "Hooke's law only holds below the yield point – beyond that the relation is no longer linear." } },
{ id: "poissons-tall",
  fig: `<svg viewBox="0 0 240 140"><rect x="60" y="55" width="70" height="30" class="dash"/><rect x="70" y="45" width="90" height="50" class="fill"/><path d="M160 70H210" class="a"/><path d="M210 70l-14-6v12z" class="af"/><path d="M70 70H20" class="a"/><path d="M20 70l14-6v12z" class="af"/><text x="180" y="66">F</text></svg>`,
  nb: { t: "Poissons tall",
    intro: "Når en stav strekkes i lengderetningen, trekker den seg litt sammen på tvers. Forholdet mellom tverrkontraksjonen og lengdetøyningen er Poissons tall $\\nu$, en materialkonstant. For de fleste metaller ligger $\\nu$ rundt 0,3.",
    f: [["\\nu = -\\dfrac{\\varepsilon_{tverr}}{\\varepsilon_{lengde}}", "Poissons tall"]],
    legend: [["\\nu", "Poissons tall", ""], ["\\varepsilon_{tverr}", "tøyning på tvers", ""], ["\\varepsilon_{lengde}", "tøyning i lengderetning", ""]],
    ex: "Stål med $\\varepsilon_{lengde} = 1$ ‰ og $\\nu = 0{,}3$:\n$\\varepsilon_{tverr} = -0{,}3\\cdot 1 = -0{,}3$ ‰.",
    tip: "Minustegnet i definisjonen gjør at $\\nu$ blir positivt for vanlige materialer som blir smalere når de strekkes." },
  en: { t: "Poisson's ratio",
    intro: "When a bar is stretched along its length, it contracts slightly across it. The ratio between the lateral contraction and the axial strain is Poisson's ratio $\\nu$, a material constant. For most metals $\\nu$ is around 0.3.",
    f: [["\\nu = -\\dfrac{\\varepsilon_{lat}}{\\varepsilon_{axial}}", "Poisson's ratio"]],
    legend: [["\\nu", "Poisson's ratio", ""], ["\\varepsilon_{lat}", "lateral strain", ""], ["\\varepsilon_{axial}", "axial strain", ""]],
    ex: "Steel with $\\varepsilon_{axial} = 1$ ‰ and $\\nu = 0.3$:\n$\\varepsilon_{lat} = -0.3\\cdot 1 = -0.3$ ‰.",
    tip: "The minus sign in the definition makes $\\nu$ positive for ordinary materials that get thinner as they stretch." } },
{ id: "termisk-spenning",
  fig: `<svg viewBox="0 0 240 140"><rect x="60" y="55" width="120" height="30" class="fill"/><path d="M40 55V95" class="b"/><path d="M200 55V95" class="b"/><path d="M40 40l14 8-14 8M40 40l-14 8 14 8" class="dash"/><path d="M200 40l14 8-14 8M200 40l-14 8 14 8" class="dash"/><text x="105" y="30">ΔT</text></svg>`,
  nb: { t: "Termisk spenning",
    intro: "En stav som varmes opp vil utvide seg, men hvis den er fastholdt i begge ender, blir utvidelsen hindret. Det gir opphav til spenning selv uten noen ytre last. Jo mer materialet «vil» utvide seg ($\\alpha$) og jo stivere det er ($E$), desto større spenning.",
    f: [["\\sigma = E\\alpha\\Delta T", "spenning fra hindret termisk utvidelse"]],
    legend: [["\\alpha", "lengdeutvidelseskoeffisient", "1/K"], ["\\Delta T", "temperaturendring", "K"], ["E", "elastisitetsmodul", "Pa"]],
    ex: "Stålstav ($E = 210$ GPa, $\\alpha = 12\\cdot10^{-6}$/K) varmes 40 K:\n$\\sigma = 210\\,000\\cdot 12\\cdot10^{-6}\\cdot 40 \\approx 100{,}8$ MPa.",
    tip: "Fortegnet: oppvarming av en fastholdt stav gir trykkspenning, nedkjøling gir strekkspenning." },
  en: { t: "Thermal stress",
    intro: "A bar that is heated wants to expand, but if it is fixed at both ends, the expansion is prevented. This creates stress even with no external load. The more the material \"wants\" to expand ($\\alpha$) and the stiffer it is ($E$), the larger the stress.",
    f: [["\\sigma = E\\alpha\\Delta T", "stress from prevented thermal expansion"]],
    legend: [["\\alpha", "coefficient of thermal expansion", "1/K"], ["\\Delta T", "temperature change", "K"], ["E", "modulus of elasticity", "Pa"]],
    ex: "A steel bar ($E = 210$ GPa, $\\alpha = 12\\cdot10^{-6}$/K) heated by 40 K:\n$\\sigma = 210\\,000\\cdot 12\\cdot10^{-6}\\cdot 40 \\approx 100.8$ MPa.",
    tip: "Sign: heating a fixed bar gives compressive stress, cooling gives tensile stress." } },
{ id: "spenningskonsentrasjon",
  fig: `<svg viewBox="0 0 240 140"><rect x="30" y="45" width="180" height="50" class="fill"/><circle cx="120" cy="70" r="16" class="dash"/><path d="M30 70H0" class="a"/><path d="M0 70l14-6v12z" class="af"/><path d="M210 70H240" class="a"/><path d="M240 70l-14-6v12z" class="af"/><text x="105" y="35">K<tspan dy="4" font-size="10">t</tspan></text></svg>`,
  nb: { t: "Spenningskonsentrasjon",
    intro: "Ved hull, kjerver og skarpe overganger blir spenningen lokalt mye høyere enn den jevnt fordelte, nominelle spenningen. Faktoren $K_t$ beskriver hvor mye høyere. Dette er spesielt viktig for utmatting, der lokale toppspenninger starter sprekker.",
    f: [["\\sigma_{maks} = K_t\\,\\sigma_{nom}", "lokal maksimal spenning"]],
    legend: [["K_t", "spenningskonsentrasjonsfaktor", ""], ["\\sigma_{nom}", "nominell (jevnt fordelt) spenning", "Pa"], ["\\sigma_{maks}", "lokal maksimal spenning", "Pa"]],
    ex: "Lite sirkulært hull i en stor plate, $K_t \\approx 3$, $\\sigma_{nom} = 50$ MPa:\n$\\sigma_{maks} \\approx 150$ MPa.",
    tip: "Myke overganger med stor radius gir lavere $K_t$ enn skarpe hjørner." },
  en: { t: "Stress concentration",
    intro: "At holes, notches and sharp transitions the stress becomes locally much higher than the uniformly distributed nominal stress. The factor $K_t$ describes how much higher. This matters especially for fatigue, where local peak stresses start cracks.",
    f: [["\\sigma_{max} = K_t\\,\\sigma_{nom}", "local maximum stress"]],
    legend: [["K_t", "stress concentration factor", ""], ["\\sigma_{nom}", "nominal (uniform) stress", "Pa"], ["\\sigma_{max}", "local maximum stress", "Pa"]],
    ex: "A small circular hole in a large plate, $K_t \\approx 3$, $\\sigma_{nom} = 50$ MPa:\n$\\sigma_{max} \\approx 150$ MPa.",
    tip: "Smooth transitions with a large radius give a lower $K_t$ than sharp corners." } }
]);

// ================= FAST – enhet 1: Torsjon og bøyning =================
TOPICS("FAST", 1, [
{ id: "torsjon",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="70" r="45" class="d"/><circle cx="120" cy="70" r="2" class="d"/><path d="M120 70L165 70" class="a"/><path d="M165 70l-6-13" class="af"/><path d="M120 70L120 25" class="dash"/><path d="M120 55a15 15 0 0 1 13 8" class="t"/><text x="140" y="58">τ</text><text x="148" y="89">r</text></svg>`,
  nb: { t: "Torsjon",
    intro: "Når en aksel utsettes for et vridningsmoment, oppstår skjærspenning som er null i sentrum og øker lineært utover mot overflaten. Det polare arealtreghetsmomentet $J$ beskriver hvor godt tverrsnittet motstår vridning.",
    f: [["\\tau = \\dfrac{Tr}{J}", "skjærspenning i avstand $r$"], ["J = \\dfrac{\\pi d^4}{32}", "polart arealtreghetsmoment, massiv sirkulær aksel"]],
    legend: [["T", "vridningsmoment", "Nm"], ["\\tau", "skjærspenning", "Pa"], ["J", "polart arealtreghetsmoment", "m⁴"], ["r", "avstand fra sentrum", "m"]],
    ex: "Aksel $d = 30$ mm, $T = 200$ Nm:\n$J = \\pi\\cdot 30^4/32 \\approx 79\\,500$ mm⁴, $\\tau_{maks} \\approx 200\\,000\\cdot 15/79\\,500 \\approx 37{,}7$ MPa.",
    tip: "Skjærspenningen er størst i overflaten – der starter torsjonsbrudd." },
  en: { t: "Torsion",
    intro: "When a shaft is subjected to a torque, shear stress arises that is zero at the center and grows linearly outward toward the surface. The polar second moment of area $J$ describes how well the cross-section resists twisting.",
    f: [["\\tau = \\dfrac{Tr}{J}", "shear stress at distance $r$"], ["J = \\dfrac{\\pi d^4}{32}", "polar second moment of area, solid circular shaft"]],
    legend: [["T", "torque", "Nm"], ["\\tau", "shear stress", "Pa"], ["J", "polar second moment of area", "m⁴"], ["r", "distance from the center", "m"]],
    ex: "A shaft with $d = 30$ mm, $T = 200$ Nm:\n$J = \\pi\\cdot 30^4/32 \\approx 79\\,500$ mm⁴, $\\tau_{max} \\approx 200\\,000\\cdot 15/79\\,500 \\approx 37.7$ MPa.",
    tip: "The shear stress is largest at the surface – that is where torsional failure starts." } },
{ id: "vridningsvinkel",
  fig: `<svg viewBox="0 0 240 140"><path d="M40 70H180" class="b"/><path d="M40 45V95" class="d"/><path d="M180 45V95" class="dash"/><path d="M180 45L200 35 M180 95L200 105" class="dash"/><path d="M170 55a15 15 0 0 1 5 15" class="t"/><text x="187" y="45">θ</text><text x="105" y="130">L</text><path d="M40 118H180M40 112v12M180 112v12" class="dim"/></svg>`,
  nb: { t: "Vridningsvinkel",
    intro: "Et vridningsmoment får ikke bare akselen til å utvikle skjærspenning, den vrir seg også en vinkel $\\theta$ over lengden. Dette er analogt med $\\delta = FL/(AE)$ for aksial forlengelse, med $G$ og $J$ i stedet for $E$ og $A$.",
    f: [["\\theta = \\dfrac{TL}{GJ}", "vridningsvinkel (radianer)"]],
    legend: [["\\theta", "vridningsvinkel", "rad"], ["L", "akselens lengde", "m"], ["G", "skjærmodul", "Pa"], ["J", "polart arealtreghetsmoment", "m⁴"]],
    ex: "Stålaksel ($G = 80$ GPa), $J = 79\\,500$ mm⁴, $L = 1$ m, $T = 200$ Nm:\n$\\theta = 200\\,000/(80\\,000\\cdot 79\\,500) \\approx 0{,}0314$ rad $\\approx 1{,}8^\\circ$.",
    tip: "Husk å regne $\\theta$ i radianer før du eventuelt gjør om til grader." },
  en: { t: "Angle of twist",
    intro: "A torque does not just cause shear stress in a shaft, it also twists it through an angle $\\theta$ over its length. This is analogous to $\\delta = FL/(AE)$ for axial elongation, with $G$ and $J$ in place of $E$ and $A$.",
    f: [["\\theta = \\dfrac{TL}{GJ}", "angle of twist (radians)"]],
    legend: [["\\theta", "angle of twist", "rad"], ["L", "length of the shaft", "m"], ["G", "shear modulus", "Pa"], ["J", "polar second moment of area", "m⁴"]],
    ex: "A steel shaft ($G = 80$ GPa), $J = 79\\,500$ mm⁴, $L = 1$ m, $T = 200$ Nm:\n$\\theta = 200\\,000/(80\\,000\\cdot 79\\,500) \\approx 0.0314$ rad $\\approx 1.8^\\circ$.",
    tip: "Remember to compute $\\theta$ in radians before converting to degrees." } },
{ id: "boyespenning-navier",
  fig: `<svg viewBox="0 0 240 140"><rect x="90" y="25" width="60" height="90" class="fill"/><path d="M60 70H180" class="dash"/><path d="M120 25V115" class="dim"/><path d="M150 30H190" class="a"/><path d="M190 30l-12-5v10z" class="af"/><path d="M150 110H190" class="r"/><path d="M190 110l-12-5v10z" class="rf"/><text x="192" y="26">σ</text><text x="65" y="65">y</text></svg>`,
  nb: { t: "Bøyespenning",
    intro: "I en bjelke som bøyes, oppstår normalspenning som varierer lineært over tverrsnittet: null på nøytralaksen, strekk på den ene siden og trykk på den andre. Navier's formel gir spenningen i en gitt avstand $y$ fra nøytralaksen.",
    f: [["\\sigma = \\dfrac{My}{I}", "bøyespenning (Naviers formel)"]],
    legend: [["M", "bøyemoment", "Nm"], ["y", "avstand fra nøytralaksen", "m"], ["I", "arealtreghetsmoment", "m⁴"]],
    ex: "Bjelke med $I = 20\\cdot10^6$ mm⁴, $M = 5$ kNm, $y = 75$ mm:\n$\\sigma = 5\\cdot10^6\\cdot 75/(20\\cdot10^6) = 18{,}75$ MPa.",
    tip: "Maksimal spenning ligger alltid i ytterfibrene, lengst unna nøytralaksen." },
  en: { t: "Bending stress",
    intro: "In a beam that is bent, normal stress arises that varies linearly across the section: zero at the neutral axis, tension on one side and compression on the other. Navier's formula gives the stress at a given distance $y$ from the neutral axis.",
    f: [["\\sigma = \\dfrac{My}{I}", "bending stress (Navier's formula)"]],
    legend: [["M", "bending moment", "Nm"], ["y", "distance from the neutral axis", "m"], ["I", "second moment of area", "m⁴"]],
    ex: "A beam with $I = 20\\cdot10^6$ mm⁴, $M = 5$ kNm, $y = 75$ mm:\n$\\sigma = 5\\cdot10^6\\cdot 75/(20\\cdot10^6) = 18.75$ MPa.",
    tip: "The maximum stress is always in the outer fibers, farthest from the neutral axis." } },
{ id: "hult-tverrsnitt",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="70" r="45" class="d"/><circle cx="120" cy="70" r="22" class="dash"/><text x="160" y="28">D</text><text x="111" y="60">d</text></svg>`,
  nb: { t: "Hule tverrsnitt",
    intro: "Materiale nær sentrum av et tverrsnitt bidrar lite til stivhet mot vridning eller bøyning, siden det ligger nær nøytralaksen. En hul aksel kan derfor gi nesten samme stivhet som en massiv med mye mindre vekt, ved å flytte materialet utover.",
    f: [["J = \\dfrac{\\pi(D^4-d^4)}{32}", "polart arealtreghetsmoment, hul sirkulær aksel"]],
    legend: [["D", "ytre diameter", "m"], ["d", "indre diameter", "m"], ["J", "polart arealtreghetsmoment", "m⁴"]],
    ex: "Hul aksel $D = 40$ mm, $d = 30$ mm:\n$J = \\pi(40^4 - 30^4)/32 \\approx 214\\,000$ mm⁴, mer enn massiv $d = 30$ mm ($\\approx 79\\,500$).",
    tip: "Hule aksler gir mye stivhet per kilo – bra der vekt er kritisk, som i fly og sykler." },
  en: { t: "Hollow cross-sections",
    intro: "Material near the center of a section contributes little to torsional or bending stiffness, since it lies close to the neutral axis. A hollow shaft can therefore give almost the same stiffness as a solid one with much less weight, by moving material outward.",
    f: [["J = \\dfrac{\\pi(D^4-d^4)}{32}", "polar second moment of area, hollow circular shaft"]],
    legend: [["D", "outer diameter", "m"], ["d", "inner diameter", "m"], ["J", "polar second moment of area", "m⁴"]],
    ex: "A hollow shaft $D = 40$ mm, $d = 30$ mm:\n$J = \\pi(40^4 - 30^4)/32 \\approx 214\\,000$ mm⁴, more than a solid $d = 30$ mm shaft ($\\approx 79\\,500$).",
    tip: "Hollow shafts give a lot of stiffness per kilogram – useful where weight is critical, as in aircraft and bicycles." } }
]);

// ================= FAST – enhet 2: Spenningstransformasjon og knekking =================
TOPICS("FAST", 2, [
{ id: "hovedspenninger-mohr",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 70H220" class="dim"/><path d="M120 130V20" class="dim"/><circle cx="130" cy="70" r="45" class="d"/><path d="M75 70H185" class="dash"/><circle cx="185" cy="70" r="2" class="d"/><circle cx="75" cy="70" r="2" class="d"/><text x="190" y="64">σ<tspan dy="4" font-size="10">1</tspan></text><text x="54" y="65">σ<tspan dy="4" font-size="10">2</tspan></text><text x="125" y="17">τ</text></svg>`,
  nb: { t: "Hovedspenninger og Mohrs sirkel",
    intro: "I et punkt med plan spenning finnes retninger der skjærspenningen er null. Normalspenningene i de retningene er hovedspenningene, største og minste normalspenning i punktet. Mohrs sirkel er en grafisk måte å finne dem på, med senter og radius fra $\\sigma_x$, $\\sigma_y$ og $\\tau_{xy}$.",
    f: [["\\sigma_{1,2} = \\dfrac{\\sigma_x+\\sigma_y}{2} \\pm \\sqrt{\\left(\\dfrac{\\sigma_x-\\sigma_y}{2}\\right)^2+\\tau_{xy}^2}", "hovedspenninger"]],
    legend: [["\\sigma_1,\\ \\sigma_2", "største/minste hovedspenning", "Pa"], ["\\tau_{xy}", "skjærspenning", "Pa"]],
    ex: "$\\sigma_x = 80$ MPa, $\\sigma_y = 20$ MPa, $\\tau_{xy} = 30$ MPa:\nsenter $= 50$, radius $= \\sqrt{30^2+30^2} \\approx 42{,}4$, så $\\sigma_1 \\approx 92{,}4$ MPa.",
    tip: "Senter i Mohrs sirkel er alltid gjennomsnittet $(\\sigma_x+\\sigma_y)/2$, uansett skjærspenning." },
  en: { t: "Principal stresses and Mohr's circle",
    intro: "At a point in plane stress there are directions where the shear stress is zero. The normal stresses in those directions are the principal stresses, the largest and smallest normal stress at the point. Mohr's circle is a graphical way to find them, with center and radius from $\\sigma_x$, $\\sigma_y$ and $\\tau_{xy}$.",
    f: [["\\sigma_{1,2} = \\dfrac{\\sigma_x+\\sigma_y}{2} \\pm \\sqrt{\\left(\\dfrac{\\sigma_x-\\sigma_y}{2}\\right)^2+\\tau_{xy}^2}", "principal stresses"]],
    legend: [["\\sigma_1,\\ \\sigma_2", "largest/smallest principal stress", "Pa"], ["\\tau_{xy}", "shear stress", "Pa"]],
    ex: "$\\sigma_x = 80$ MPa, $\\sigma_y = 20$ MPa, $\\tau_{xy} = 30$ MPa:\ncenter $= 50$, radius $= \\sqrt{30^2+30^2} \\approx 42.4$, so $\\sigma_1 \\approx 92.4$ MPa.",
    tip: "The center of Mohr's circle is always the average $(\\sigma_x+\\sigma_y)/2$, regardless of the shear stress." } },
{ id: "von-mises",
  fig: `<svg viewBox="0 0 240 140"><rect x="80" y="40" width="80" height="60" class="fill"/><path d="M160 55H200" class="a"/><path d="M200 55l-12-5v10z" class="af"/><path d="M80 85H40" class="a"/><path d="M40 85l12-5v10z" class="af"/><path d="M80 40V15 M100 40V15" class="t"/><path d="M80 15H120" class="t"/><text x="205" y="50">σ</text><text x="15" y="80">σ</text><text x="95" y="15">τ</text></svg>`,
  nb: { t: "Von Mises-spenning",
    intro: "Von Mises-spenningen kombinerer flere spenningskomponenter til én ekvivalent spenning som kan sammenlignes direkte med flytegrensen. Kriteriet sier at materialet flyter når den ekvivalente spenningen når $R_e$, og brukes mest for duktile materialer.",
    f: [["\\sigma_v = \\sqrt{\\sigma^2 + 3\\tau^2}", "von Mises, enakset spenning med skjær"]],
    legend: [["\\sigma_v", "von Mises-spenning", "Pa"], ["\\sigma", "normalspenning", "Pa"], ["\\tau", "skjærspenning", "Pa"]],
    ex: "$\\sigma = 100$ MPa, $\\tau = 40$ MPa:\n$\\sigma_v = \\sqrt{100^2+3\\cdot40^2} \\approx 131$ MPa.",
    tip: "Sammenlign alltid $\\sigma_v$ med flytegrensen $R_e$, ikke med bruddgrensen $R_m$, for duktile materialer." },
  en: { t: "Von Mises stress",
    intro: "The von Mises stress combines several stress components into one equivalent stress that can be compared directly with the yield strength. The criterion states that the material yields when the equivalent stress reaches $R_e$, and it is used mostly for ductile materials.",
    f: [["\\sigma_v = \\sqrt{\\sigma^2 + 3\\tau^2}", "von Mises, uniaxial stress with shear"]],
    legend: [["\\sigma_v", "von Mises stress", "Pa"], ["\\sigma", "normal stress", "Pa"], ["\\tau", "shear stress", "Pa"]],
    ex: "$\\sigma = 100$ MPa, $\\tau = 40$ MPa:\n$\\sigma_v = \\sqrt{100^2+3\\cdot40^2} \\approx 131$ MPa.",
    tip: "Always compare $\\sigma_v$ with the yield strength $R_e$, not the ultimate strength $R_m$, for ductile materials." } },
{ id: "eulers-knekklast",
  fig: `<svg viewBox="0 0 240 140"><path d="M120 120V50Q95 35 120 20" class="b"/><path d="M90 125H150 M90 125V132 M150 125V132" class="dim"/><path d="M120 20V10" class="a"/><path d="M120 10l-6 10h12z" class="af"/><text x="128" y="15">P</text><text x="128" y="75">L</text></svg>`,
  nb: { t: "Eulers knekklast",
    intro: "En slank søyle i trykk kan svikte ved at den plutselig bøyer ut til siden (knekking), lenge før spenningen når flytegrensen. Eulers formel gir den kritiske lasten som starter knekking, og den avtar raskt med økende lengde.",
    f: [["P_{cr} = \\dfrac{\\pi^2EI}{(KL)^2}", "Eulers knekklast"]],
    legend: [["P_{cr}", "kritisk knekklast", "N"], ["I", "minste arealtreghetsmoment", "m⁴"], ["K", "effektiv lengdefaktor", ""], ["L", "søylens lengde", "m"]],
    ex: "Stålsøyle leddet i begge ender ($K=1$), $L = 2$ m, $I = 5\\cdot10^5$ mm⁴:\n$P_{cr} = \\pi^2\\cdot 210\\,000\\cdot 5\\cdot10^5/2000^2 \\approx 259$ kN.",
    tip: "Dobler du lengden, blir knekklasten en firedel – bruk minste $I$ i tverrsnittet." },
  en: { t: "Euler buckling load",
    intro: "A slender column in compression can fail by suddenly bowing out sideways (buckling), long before the stress reaches the yield point. Euler's formula gives the critical load that triggers buckling, and it drops off quickly with increasing length.",
    f: [["P_{cr} = \\dfrac{\\pi^2EI}{(KL)^2}", "Euler buckling load"]],
    legend: [["P_{cr}", "critical buckling load", "N"], ["I", "smallest second moment of area", "m⁴"], ["K", "effective length factor", ""], ["L", "column length", "m"]],
    ex: "A steel column pinned at both ends ($K=1$), $L = 2$ m, $I = 5\\cdot10^5$ mm⁴:\n$P_{cr} = \\pi^2\\cdot 210\\,000\\cdot 5\\cdot10^5/2000^2 \\approx 259$ kN.",
    tip: "Doubling the length quarters the buckling load – use the smallest $I$ of the section." } },
{ id: "knekklengde",
  fig: `<svg viewBox="0 0 240 140"><path d="M50 120V25" class="b"/><path d="M35 120H65 M35 120V127 M65 120V127" class="dim"/><path d="M120 120V25" class="b"/><circle cx="120" cy="25" r="3" class="d"/><path d="M105 120H135 M105 120V127 M135 120V127" class="dim"/><circle cx="120" cy="120" r="3" class="d"/><path d="M190 120V25" class="b"/><path d="M175 120H205 M175 120V127 M205 120V127" class="dim"/><text x="40" y="18">K<tspan dy="4" font-size="10">2</tspan></text><text x="111" y="17">K<tspan dy="4" font-size="10">1</tspan></text><text x="178" y="18">K<tspan dy="4" font-size="10">.5</tspan></text></svg>`,
  nb: { t: "Knekklengde",
    intro: "Hvordan søylens ender er festet, påvirker hvor lett den knekker. Faktoren $K$ omregner den virkelige lengden til en effektiv knekklengde $KL$, som tilsvarer en tenkt leddet søyle med samme knekklast. Fastere innspenning gir mindre $K$ og dermed høyere knekklast.",
    f: [["L_{eff} = KL", "effektiv knekklengde"]],
    legend: [["K", "effektiv lengdefaktor", ""], ["L", "søylens virkelige lengde", "m"]],
    ex: "Søyle innspent i begge ender, $L = 3$ m:\n$K = 0{,}5$, så $L_{eff} = 1{,}5$ m – gir 16 ganger så stor knekklast som $K=2$.",
    tip: "Leddet i begge ender gir $K=1$; innspent i den ene og fri i den andre gir $K=2$, verst mulig." },
  en: { t: "Effective length",
    intro: "How the ends of a column are supported affects how easily it buckles. The factor $K$ converts the real length into an effective buckling length $KL$, equivalent to an imaginary pinned column with the same buckling load. A stiffer fixation gives a smaller $K$ and thus a higher buckling load.",
    f: [["L_{eff} = KL", "effective buckling length"]],
    legend: [["K", "effective length factor", ""], ["L", "actual column length", "m"]],
    ex: "A column fixed at both ends, $L = 3$ m:\n$K = 0.5$, so $L_{eff} = 1.5$ m – gives 16 times the buckling load of $K=2$.",
    tip: "Pinned at both ends gives $K=1$; fixed at one end and free at the other gives $K=2$, the worst case." } }
]);

// ================= MATS1600 – enhet 0: Spenning og dimensjonering =================
TOPICS("MATS1600", 0, [
{ id: "normalspenning",
  fig: `<svg viewBox="0 0 240 140"><rect x="80" y="50" width="60" height="40" class="fill"/><path d="M140 70H195" class="a"/><path d="M195 70l-14-6v12z" class="af"/><path d="M80 70H25" class="a"/><path d="M25 70l14-6v12z" class="af"/><text x="197" y="66">F</text><text x="105" y="115">A</text></svg>`,
  nb: { t: "Normalspenning",
    intro: "Normalspenning er kraften delt på tverrsnittsarealet, og er utgangspunktet for all dimensjonering mot strekk og trykk. Jevn fordeling forutsetter at kraften angriper i tyngdepunktet av tverrsnittet og at tverrsnittet er langt fra hull eller kjerver.",
    f: [["\\sigma = F/A", "normalspenning"]],
    legend: [["\\sigma", "normalspenning", "Pa"], ["F", "aksialkraft", "N"], ["A", "tverrsnittsareal", "m²"]],
    ex: "Stav med $A = 100$ mm², $F = 10$ kN:\n$\\sigma = 10\\,000/100 = 100$ N/mm² $= 100$ MPa.",
    tip: "1 N/mm² = 1 MPa – en praktisk snarvei når kreftene er i N og lengder i mm." },
  en: { t: "Normal stress",
    intro: "Normal stress is the force divided by the cross-sectional area, and it is the starting point for all sizing against tension and compression. Uniform distribution assumes the force acts through the centroid of the section and that the section is far from holes or notches.",
    f: [["\\sigma = F/A", "normal stress"]],
    legend: [["\\sigma", "normal stress", "Pa"], ["F", "axial force", "N"], ["A", "cross-sectional area", "m²"]],
    ex: "A bar with $A = 100$ mm², $F = 10$ kN:\n$\\sigma = 10\\,000/100 = 100$ N/mm² $= 100$ MPa.",
    tip: "1 N/mm² = 1 MPa – a handy shortcut when forces are in N and lengths in mm." } },
{ id: "sikkerhetsfaktor",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 110H210" class="dim"/><rect x="30" y="40" width="90" height="70" class="fill"/><rect x="120" y="60" width="60" height="50" class="dash"/><text x="45" y="30">R<tspan dy="4" font-size="10">e</tspan></text><text x="135" y="52">σ</text></svg>`,
  nb: { t: "Sikkerhetsfaktor",
    intro: "Sikkerhetsfaktoren viser hvor stor margin en konstruksjon har mot å flyte eller ryke, og tar høyde for usikkerhet i last, materiale og modell. Jo høyere $n$, desto større margin, men også mer materiale og vekt.",
    f: [["n = \\dfrac{R_e}{\\sigma_{faktisk}}", "sikkerhetsfaktor mot flyt"]],
    legend: [["n", "sikkerhetsfaktor", ""], ["R_e", "flytegrense", "Pa"], ["\\sigma_{faktisk}", "faktisk (regnet) spenning", "Pa"]],
    ex: "Stål med $R_e = 355$ MPa, faktisk spenning 142 MPa:\n$n = 355/142 \\approx 2{,}5$.",
    tip: "$n > 1$ betyr margin mot flyt, ikke at konstruksjonen tåler $n$ ganger lasten uten skade." },
  en: { t: "Safety factor",
    intro: "The safety factor shows how much margin a structure has against yielding or fracture, accounting for uncertainty in load, material and model. The higher $n$ is, the larger the margin, but also more material and weight.",
    f: [["n = \\dfrac{R_e}{\\sigma_{actual}}", "safety factor against yield"]],
    legend: [["n", "safety factor", ""], ["R_e", "yield strength", "Pa"], ["\\sigma_{actual}", "actual (computed) stress", "Pa"]],
    ex: "Steel with $R_e = 355$ MPa, actual stress 142 MPa:\n$n = 355/142 \\approx 2.5$.",
    tip: "$n > 1$ means margin against yield, not that the structure can take $n$ times the load undamaged." } },
{ id: "toyning-e-modul",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 120H220" class="dim"/><path d="M30 120V20" class="dim"/><path d="M30 120L150 40" class="a"/><path d="M150 40L190 25" class="dash"/><text x="10" y="70">σ</text><text x="130" y="130">ε</text></svg>`,
  nb: { t: "Tøyning og E-modul",
    intro: "I det lineærelastiske området er spenning og tøyning proporsjonale. Stigningstallet i $\\sigma$–$\\varepsilon$-diagrammet er elastisitetsmodulen $E$, en materialegenskap som forteller hvor stivt materialet er. Stål har mye høyere $E$ enn aluminium eller plast.",
    f: [["\\varepsilon = \\sigma/E", "tøyning fra Hookes lov"]],
    legend: [["\\varepsilon", "tøyning", ""], ["\\sigma", "spenning", "Pa"], ["E", "elastisitetsmodul", "Pa"]],
    ex: "Stål, $E = 210$ GPa, $\\sigma = 210$ MPa:\n$\\varepsilon = 210/210\\,000 = 0{,}001 = 1$ ‰.",
    tip: "$E$ er en materialkonstant og er uavhengig av tverrsnittets form eller størrelse." },
  en: { t: "Strain and modulus of elasticity",
    intro: "In the linear elastic range, stress and strain are proportional. The slope in the $\\sigma$–$\\varepsilon$ diagram is the modulus of elasticity $E$, a material property showing how stiff the material is. Steel has a much higher $E$ than aluminum or plastic.",
    f: [["\\varepsilon = \\sigma/E", "strain from Hooke's law"]],
    legend: [["\\varepsilon", "strain", ""], ["\\sigma", "stress", "Pa"], ["E", "modulus of elasticity", "Pa"]],
    ex: "Steel, $E = 210$ GPa, $\\sigma = 210$ MPa:\n$\\varepsilon = 210/210\\,000 = 0.001 = 1$ ‰.",
    tip: "$E$ is a material constant and does not depend on the shape or size of the cross-section." } },
{ id: "boyespenning-w",
  fig: `<svg viewBox="0 0 240 140"><rect x="90" y="25" width="60" height="90" class="fill"/><path d="M60 70H180" class="dash"/><text x="65" y="65">y</text><text x="128" y="20">σ<tspan dy="4" font-size="10">maks</tspan></text></svg>`,
  nb: { t: "Bøyespenning og motstandsmoment",
    intro: "For dimensjonering av bjelker er den maksimale bøyespenningen, ytterst i tverrsnittet, det som teller. Ved å samle $I$ og avstanden til ytterkant $y_{maks}$ i motstandsmomentet $W$, blir formelen enkel: $\\sigma_{maks} = M/W$.",
    f: [["W = I/y_{maks}", "motstandsmoment"], ["\\sigma_{maks} = M/W", "maksimal bøyespenning"]],
    legend: [["W", "motstandsmoment", "m³"], ["I", "arealtreghetsmoment", "m⁴"], ["M", "bøyemoment", "Nm"]],
    ex: "Rektangel $b=50$, $h=100$ mm: $W = bh^2/6 = 83\\,300$ mm³.\nMed $M = 2$ kNm: $\\sigma_{maks} = 2\\cdot10^6/83\\,300 \\approx 24$ MPa.",
    tip: "$W = bh^2/6$ for et rektangel – merk andre potens på høyden, mot tredje for $I$." },
  en: { t: "Bending stress and section modulus",
    intro: "For sizing beams, the maximum bending stress, at the outer edge of the section, is what matters. By combining $I$ and the distance to the outer edge $y_{max}$ into the section modulus $W$, the formula becomes simple: $\\sigma_{max} = M/W$.",
    f: [["W = I/y_{max}", "section modulus"], ["\\sigma_{max} = M/W", "maximum bending stress"]],
    legend: [["W", "section modulus", "m³"], ["I", "second moment of area", "m⁴"], ["M", "bending moment", "Nm"]],
    ex: "A rectangle $b=50$, $h=100$ mm: $W = bh^2/6 = 83\\,300$ mm³.\nWith $M = 2$ kNm: $\\sigma_{max} = 2\\cdot10^6/83\\,300 \\approx 24$ MPa.",
    tip: "$W = bh^2/6$ for a rectangle – note the second power on the height, versus the third for $I$." } }
]);

// ================= MATS1600 – enhet 1: Toleranser og passninger =================
TOPICS("MATS1600", 1, [
{ id: "klaring-press",
  fig: `<svg viewBox="0 0 240 140"><circle cx="65" cy="70" r="35" class="fill"/><circle cx="65" cy="70" r="28" class="dash"/><circle cx="175" cy="70" r="28" class="fill"/><circle cx="175" cy="70" r="32" class="dash"/><text x="45" y="28">H7</text><text x="160" y="28">H7</text></svg>`,
  nb: { t: "Klarings- og presspassning",
    intro: "En passning beskriver hvordan en aksel og et hull med samme nominelle mål passer sammen. Ved klaringspassning er akselen alltid litt mindre enn hullet, slik at delene kan skyves sammen for hånd. Ved presspassning er akselen litt større, og delene må presses eller krympes sammen for å gi grep ved friksjon.",
    f: [["\\text{Klaring: } d_{aksel} < D_{hull}", "delene har alltid klaring"], ["\\text{Press: } d_{aksel} > D_{hull}", "delene har alltid overmål"]],
    legend: [["d_{aksel}", "akseldiameter", "mm"], ["D_{hull}", "hulldiameter", "mm"]],
    ex: "H7/g6 er en klaringspassning:\ng-akselen ligger alltid under nominelt mål, H-hullet alltid over.",
    tip: "H7/g6 gir alltid klaring, H7/p6 gir alltid press – bokstaven på akselen avgjør typen." },
  en: { t: "Clearance and press fits",
    intro: "A fit describes how a shaft and a hole with the same nominal size go together. In a clearance fit the shaft is always a bit smaller than the hole, so the parts slide together by hand. In a press fit the shaft is a bit larger, and the parts must be pressed or shrink-fitted together to grip by friction.",
    f: [["\\text{Clearance: } d_{shaft} < D_{hole}", "the parts always have clearance"], ["\\text{Press: } d_{shaft} > D_{hole}", "the parts always have interference"]],
    legend: [["d_{shaft}", "shaft diameter", "mm"], ["D_{hole}", "hole diameter", "mm"]],
    ex: "H7/g6 is a clearance fit:\nthe g shaft is always below nominal size, the H hole always above.",
    tip: "H7/g6 always gives clearance, H7/p6 always gives interference – the shaft letter decides the type." } },
{ id: "hullbasissystem",
  fig: `<svg viewBox="0 0 240 140"><path d="M40 100H200" class="dim"/><rect x="70" y="45" width="100" height="40" class="fill"/><path d="M70 45H170" class="d"/><text x="30" y="105">0</text><text x="105" y="40">H7</text></svg>`,
  nb: { t: "Hullbasissystem (IT-toleranser)",
    intro: "For å slippe å lage hull i alle mulige mål, brukes hullbasissystemet: hullet får alltid nedre grenseavvik lik null (bokstav H), og passningstypen styres i stedet av akselens toleransefelt. IT-graden (f.eks. IT7) angir hvor stor selve toleransen, spennvidden, er.",
    f: [["\\text{H-hull: nedre avvik} = 0", "definisjon av hullbasissystemet"]],
    legend: [["H", "toleransefelt der nedre avvik er null", ""], ["IT", "toleransegrad (spennvidde)", ""]],
    ex: "H7-hull med nominelt mål 30 mm:\nminste mål er nøyaktig 30,000 mm, største bestemmes av IT7.",
    tip: "Bare hullet er «H»; det er bokstaven og tallet på akselen som avgjør om det blir klaring eller press." },
  en: { t: "Hole-basis system (IT tolerances)",
    intro: "To avoid having to make holes in every possible size, the hole-basis system is used: the hole always gets a lower deviation of zero (letter H), and the type of fit is instead controlled by the shaft's tolerance zone. The IT grade (e.g. IT7) states how large the tolerance span itself is.",
    f: [["\\text{H hole: lower deviation} = 0", "definition of the hole-basis system"]],
    legend: [["H", "tolerance zone with zero lower deviation", ""], ["IT", "tolerance grade (span)", ""]],
    ex: "An H7 hole with nominal size 30 mm:\nthe smallest size is exactly 30.000 mm, the largest is set by IT7.",
    tip: "Only the hole is \"H\"; it is the shaft's letter and number that decide clearance or interference." } },
{ id: "overflateruhet",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 70H220" class="dim"/><path d="M30 70Q45 50 60 70T90 70T120 70T150 70T180 70T210 70" class="d"/><text x="115" y="30">R<tspan dy="4" font-size="10">a</tspan></text></svg>`,
  nb: { t: "Overflateruhet (Ra)",
    intro: "Ingen overflate er helt glatt – den har mikroskopiske topper og daler. $R_a$ er det aritmetiske middelavviket til overflateprofilen fra en gjennomsnittslinje, og angis i mikrometer. Lavere $R_a$ betyr en finere, glattere overflate, som ofte krever mer bearbeiding.",
    f: [["R_a = \\dfrac{1}{L}\\int_0^L |y(x)|\\,dx", "aritmetisk middelavvik"]],
    legend: [["R_a", "overflateruhet", "µm"], ["y(x)", "profilhøyde fra middellinjen", "µm"], ["L", "målelengde", "mm"]],
    ex: "En slipt overflate har typisk $R_a \\approx 0{,}4$ µm,\nmens en dreid overflate kan ligge på $R_a \\approx 3{,}2$ µm.",
    tip: "Krev ikke lavere $R_a$ enn funksjonen faktisk trenger – finbearbeiding koster mye." },
  en: { t: "Surface roughness (Ra)",
    intro: "No surface is perfectly smooth – it has microscopic peaks and valleys. $R_a$ is the arithmetic mean deviation of the surface profile from a mean line, given in micrometers. A lower $R_a$ means a finer, smoother surface, which usually requires more machining.",
    f: [["R_a = \\dfrac{1}{L}\\int_0^L |y(x)|\\,dx", "arithmetic mean deviation"]],
    legend: [["R_a", "surface roughness", "µm"], ["y(x)", "profile height from the mean line", "µm"], ["L", "sampling length", "mm"]],
    ex: "A ground surface typically has $R_a \\approx 0.4$ µm,\nwhile a turned surface may be around $R_a \\approx 3.2$ µm.",
    tip: "Do not specify a lower $R_a$ than the function actually needs – fine finishing is costly." } }
]);

// ================= MATS1600 – enhet 2: Maskinelementer =================
TOPICS("MATS1600", 2, [
{ id: "utveksling",
  fig: `<svg viewBox="0 0 240 140"><circle cx="70" cy="70" r="35" class="d"/><circle cx="70" cy="70" r="4" class="d"/><circle cx="175" cy="70" r="18" class="d"/><circle cx="175" cy="70" r="3" class="d"/><path d="M60 40a15 15 0 0 1 10 -3" class="t"/><path d="M70 37l-11 3 8 8z" class="tf"/><text x="55" y="25">n<tspan dy="4" font-size="10">1</tspan></text><text x="180" y="56">n<tspan dy="4" font-size="10">2</tspan></text></svg>`,
  nb: { t: "Utveksling",
    intro: "Et tannhjulpar eller en reim endrer turtall og moment mellom en drivende og en drevet aksel. Utvekslingsforholdet er forholdet mellom antall tenner (eller diametre), og turtallet endres motsatt av momentet: går turtallet ned, går momentet opp, omtrent i samme forhold.",
    f: [["i = \\dfrac{z_2}{z_1} = \\dfrac{n_1}{n_2}", "utvekslingsforhold"]],
    legend: [["i", "utvekslingsforhold", ""], ["z_1,\\ z_2", "antall tenner på drivende/drevet hjul", ""], ["n_1,\\ n_2", "turtall inn/ut", "rpm"]],
    ex: "Drivhjul med 20 tenner driver hjul med 60 tenner:\n$i = 60/20 = 3$, så turtallet ut blir en tredjedel.",
    tip: "Turtallet ned og momentet opp følger omtrent samme forhold $i$ – energien er (nesten) bevart." },
  en: { t: "Gear ratio",
    intro: "A gear pair or a belt changes the speed and torque between a driving and a driven shaft. The gear ratio is the ratio of the number of teeth (or diameters), and the speed changes opposite to the torque: if the speed drops, the torque rises, roughly by the same ratio.",
    f: [["i = \\dfrac{z_2}{z_1} = \\dfrac{n_1}{n_2}", "gear ratio"]],
    legend: [["i", "gear ratio", ""], ["z_1,\\ z_2", "number of teeth on driving/driven gear", ""], ["n_1,\\ n_2", "input/output speed", "rpm"]],
    ex: "A 20-tooth driving gear drives a 60-tooth gear:\n$i = 60/20 = 3$, so the output speed is a third.",
    tip: "Speed down and torque up follow roughly the same ratio $i$ – energy is (nearly) conserved." } },
{ id: "effekt-moment",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="70" r="40" class="d"/><path d="M120 70L120 32" class="a"/><path d="M120 32l-6 12h12z" class="af"/><path d="M100 45a26 26 0 0 1 40 8" class="t"/><path d="M140 53l11 2 -8 9z" class="tf"/><text x="128" y="23">M</text><text x="149" y="45">ω</text></svg>`,
  nb: { t: "Effekt, moment og turtall",
    intro: "Effekten en aksel overfører henger sammen med momentet og vinkelhastigheten. Dette er nyttig når du skal velge motorstørrelse eller regne om mellom moment og effekt ved kjent turtall, for eksempel for en motor eller en pumpe.",
    f: [["P = M\\omega", "effekt fra moment og vinkelhastighet"], ["\\omega = \\dfrac{2\\pi n}{60}", "vinkelhastighet fra turtall"]],
    legend: [["P", "effekt", "W"], ["M", "moment", "Nm"], ["\\omega", "vinkelhastighet", "rad/s"], ["n", "turtall", "rpm"]],
    ex: "Moment 100 Nm ved 300 rad/s:\n$P = 100\\cdot 300 = 30\\,000$ W $= 30$ kW.",
    tip: "Regn alltid om turtall (rpm) til $\\omega$ (rad/s) før du bruker $P = M\\omega$." },
  en: { t: "Power, torque and speed",
    intro: "The power transmitted by a shaft is linked to the torque and the angular velocity. This is useful when choosing a motor size or converting between torque and power at a known speed, for example for a motor or a pump.",
    f: [["P = M\\omega", "power from torque and angular velocity"], ["\\omega = \\dfrac{2\\pi n}{60}", "angular velocity from speed"]],
    legend: [["P", "power", "W"], ["M", "torque", "Nm"], ["\\omega", "angular velocity", "rad/s"], ["n", "rotational speed", "rpm"]],
    ex: "A torque of 100 Nm at 300 rad/s:\n$P = 100\\cdot 300 = 30\\,000$ W $= 30$ kW.",
    tip: "Always convert speed (rpm) to $\\omega$ (rad/s) before using $P = M\\omega$." } },
{ id: "boltforspenning",
  fig: `<svg viewBox="0 0 240 140"><rect x="60" y="70" width="120" height="14" class="fill"/><rect x="60" y="84" width="120" height="14" class="fill"/><path d="M115 55V125" class="b"/><path d="M105 55h20l-4 -14h-12z" class="d"/><path d="M105 125h20l-4 14h-12z" class="d"/><path d="M115 30V15" class="a"/><path d="M115 15l-6 10h12z" class="af"/><path d="M115 130V145" class="a"/><path d="M115 145l6-10h-12z" class="af"/><text x="123" y="24">F<tspan dy="4" font-size="10">i</tspan></text></svg>`,
  nb: { t: "Boltforspenning",
    intro: "En bolt strammes ofte til med en forspenningskraft som er langt større enn den ytre lasten. Forspenningen holder delene sammenpresset, slik at de ikke glipper, og gjør at bolten selv bare ser en liten del av en varierende ytre last – noe som beskytter mot utmatting.",
    f: [["F_i \\gg F_{ytre}", "forspenning bør være langt større enn ytre last"]],
    legend: [["F_i", "forspenningskraft", "N"], ["F_{ytre}", "ytre (varierende) last på forbindelsen", "N"]],
    ex: "En flensforbindelse med svingende last:\nhøy forspenning gjør at bolten opplever en langt mindre svingning enn selve lasten.",
    tip: "Riktig tiltrekkingsmoment er avgjørende – for lite gir glipp, for mye kan skade bolten." },
  en: { t: "Bolt preload",
    intro: "A bolt is often tightened with a preload force far larger than the external load. The preload keeps the parts pressed together so they do not separate, and it means the bolt itself only sees a small part of a varying external load – which protects against fatigue.",
    f: [["F_i \\gg F_{ext}", "preload should be far larger than the external load"]],
    legend: [["F_i", "preload force", "N"], ["F_{ext}", "external (varying) load on the joint", "N"]],
    ex: "A flange joint with a fluctuating load:\nhigh preload means the bolt experiences a far smaller fluctuation than the load itself.",
    tip: "The correct tightening torque matters – too little causes joint separation, too much can damage the bolt." } },
{ id: "lagertyper",
  fig: `<svg viewBox="0 0 240 140"><circle cx="75" cy="70" r="35" class="d"/><circle cx="75" cy="70" r="20" class="d"/><circle cx="75" cy="45" r="4" class="d"/><circle cx="97" cy="57" r="4" class="d"/><circle cx="97" cy="83" r="4" class="d"/><circle cx="75" cy="95" r="4" class="d"/><circle cx="53" cy="83" r="4" class="d"/><circle cx="53" cy="57" r="4" class="d"/><rect x="140" y="50" width="70" height="40" class="fill"/><circle cx="175" cy="70" r="18" class="dash"/></svg>`,
  nb: { t: "Rullelager og glidelager",
    intro: "Rullelager (f.eks. kulelager) har rullende elementer mellom ringene og gir lav friksjon selv ved oppstart. Glidelager har en smørefilm mellom akselen og en fast bøssing; de trenger fart for å bygge opp filmen, men kan være svært stille og robuste ved høye turtall og store laster.",
    f: [["\\text{Rullelager: lav friksjon, også i ro}", "kule- eller rullelager"], ["\\text{Glidelager: krever fart for smørefilm}", "hydrodynamisk smøring"]],
    legend: [["\\mu", "friksjonskoeffisient i lageret", ""]],
    ex: "Rullelager starter lett fra ro,\nmens et glidelager kan gi metallkontakt og høy friksjon rett ved oppstart.",
    tip: "Velg glidelager for svært høye turtall og støtbelastning, rullelager der oppstart uten smørefilm er vanlig." },
  en: { t: "Rolling and plain bearings",
    intro: "Rolling bearings (e.g. ball bearings) have rolling elements between the rings and give low friction even at start-up. Plain (sliding) bearings have a lubricant film between the shaft and a fixed bushing; they need speed to build up the film, but can be very quiet and robust at high speeds and heavy loads.",
    f: [["\\text{Rolling: low friction, even at rest}", "ball or roller bearing"], ["\\text{Plain: needs speed for the film}", "hydrodynamic lubrication"]],
    legend: [["\\mu", "friction coefficient in the bearing", ""]],
    ex: "A rolling bearing starts easily from rest,\nwhile a plain bearing can have metal contact and high friction right at start-up.",
    tip: "Choose plain bearings for very high speeds and shock loading, rolling bearings where start-up without a film is common." } }
]);

// ================= SVING – enhet 0: Frie svingninger =================
TOPICS("SVING", 0, [
{ id: "egenfrekvens",
  fig: `<svg viewBox="0 0 240 140"><path d="M60 20V45" class="d"/><path d="M60 45q10 8 0 16t0 16t0 16" class="d"/><rect x="35" y="93" width="50" height="30" class="fill"/><path d="M20 20H100" class="dim"/><path d="M108 90V50" class="a"/><path d="M108 50l-6 12h12z" class="af"/><text x="116" y="72">x</text></svg>`,
  nb: { t: "Egenfrekvens",
    intro: "Et masse–fjær-system som forstyrres fra likevekt, svinger med en bestemt frekvens hvis ingen ytre kraft virker videre – egenfrekvensen. Den avhenger bare av stivheten $k$ og massen $m$, ikke av hvor stort utslaget er.",
    f: [["\\omega_n = \\sqrt{k/m}", "egen vinkelfrekvens"], ["f_n = \\dfrac{\\omega_n}{2\\pi}", "egenfrekvens"]],
    legend: [["\\omega_n", "egen vinkelfrekvens", "rad/s"], ["f_n", "egenfrekvens", "Hz"], ["k", "fjærstivhet", "N/m"], ["m", "masse", "kg"]],
    ex: "Maskin på 5 kg på fjærer med $k = 10$ kN/m:\n$f_n = \\dfrac{1}{2\\pi}\\sqrt{10\\,000/5} \\approx 7{,}12$ Hz.",
    tip: "Firedobler du massen, halveres egenfrekvensen – den følger $1/\\sqrt m$, ikke $1/m$." },
  en: { t: "Natural frequency",
    intro: "A mass–spring system disturbed from equilibrium oscillates at a particular frequency if no external force continues to act – the natural frequency. It depends only on the stiffness $k$ and the mass $m$, not on how large the amplitude is.",
    f: [["\\omega_n = \\sqrt{k/m}", "natural angular frequency"], ["f_n = \\dfrac{\\omega_n}{2\\pi}", "natural frequency"]],
    legend: [["\\omega_n", "natural angular frequency", "rad/s"], ["f_n", "natural frequency", "Hz"], ["k", "spring stiffness", "N/m"], ["m", "mass", "kg"]],
    ex: "A 5 kg machine on springs with $k = 10$ kN/m:\n$f_n = \\dfrac{1}{2\\pi}\\sqrt{10\\,000/5} \\approx 7.12$ Hz.",
    tip: "Quadrupling the mass halves the natural frequency – it follows $1/\\sqrt m$, not $1/m$." } },
{ id: "fjaerer-serie-parallell",
  fig: `<svg viewBox="0 0 240 140"><path d="M40 30V50" class="d"/><path d="M40 50q10 6 0 12t0 12t0 12t0 12" class="d"/><path d="M40 98V115" class="d"/><path d="M120 30V50" class="d"/><path d="M120 50q10 6 0 12t0 12t0 12t0 12" class="d"/><path d="M120 98V115" class="d"/><path d="M40 115H120" class="d"/><path d="M80 115V128" class="d"/><path d="M170 30V45" class="d"/><path d="M170 45q10 5 0 10t0 10t0 10" class="d"/><path d="M170 75V85" class="d"/><path d="M170 85q10 5 0 10t0 10t0 10" class="d"/><path d="M170 115V128" class="d"/><text x="29" y="25">k<tspan dy="4" font-size="10">1</tspan></text><text x="110" y="25">k<tspan dy="4" font-size="10">2</tspan></text><text x="177" y="60">k<tspan dy="4" font-size="10">1</tspan></text></svg>`,
  nb: { t: "Fjærer i serie og parallell",
    intro: "Når flere fjærer bærer samme masse, kan de erstattes med én ekvivalent fjær. I parallell deler de forskyvningen likt, og stivhetene legges sammen. I serie deler de kraften likt, og det er de fleksibilitetene (1/k) som legges sammen, akkurat som for elektriske motstander.",
    f: [["k_{par} = k_1 + k_2", "fjærer i parallell"], ["k_{ser} = \\dfrac{k_1k_2}{k_1+k_2}", "fjærer i serie"]],
    legend: [["k_{par},\\ k_{ser}", "ekvivalent stivhet", "N/m"], ["k_1,\\ k_2", "enkeltfjærers stivhet", "N/m"]],
    ex: "To fjærer på 200 N/m og 300 N/m i serie:\n$k_{ser} = 200\\cdot 300/500 = 120$ N/m.",
    tip: "I serie blir ekvivalent stivhet alltid mindre enn den svakeste fjæren alene." },
  en: { t: "Springs in series and parallel",
    intro: "When several springs carry the same mass, they can be replaced by one equivalent spring. In parallel they share the displacement equally, and the stiffnesses add. In series they share the force equally, and it is the flexibilities (1/k) that add, just like for electrical resistors.",
    f: [["k_{par} = k_1 + k_2", "springs in parallel"], ["k_{ser} = \\dfrac{k_1k_2}{k_1+k_2}", "springs in series"]],
    legend: [["k_{par},\\ k_{ser}", "equivalent stiffness", "N/m"], ["k_1,\\ k_2", "individual spring stiffness", "N/m"]],
    ex: "Two springs of 200 N/m and 300 N/m in series:\n$k_{ser} = 200\\cdot 300/500 = 120$ N/m.",
    tip: "In series the equivalent stiffness is always less than the weakest spring alone." } },
{ id: "statisk-nedboyning",
  fig: `<svg viewBox="0 0 240 140"><path d="M120 15V45" class="d"/><path d="M120 45q10 6 0 12t0 12" class="d"/><path d="M120 69V80" class="d"/><rect x="95" y="80" width="50" height="25" class="fill"/><path d="M50 45H200" class="dim"/><path d="M50 69H200" class="dash"/><text x="30" y="60">δ</text></svg>`,
  nb: { t: "Statisk nedbøyning og frekvens",
    intro: "Hvis du kjenner den statiske nedbøyningen $\\delta$ en masse gir på fjæren sin, kan du finne egenfrekvensen uten å vite verken $k$ eller $m$ hver for seg. Dette kommer av at $k\\delta = mg$, som gir $k/m = g/\\delta$ direkte inn i formelen for $\\omega_n$.",
    f: [["\\omega_n = \\sqrt{g/\\delta}", "egen vinkelfrekvens fra statisk nedbøyning"]],
    legend: [["\\delta", "statisk nedbøyning", "m"], ["g", "tyngdeakselerasjon", "m/s²"]],
    ex: "Statisk nedbøyning $\\delta = 5$ mm:\n$\\omega_n = \\sqrt{9{,}81/0{,}005} \\approx 44{,}3$ rad/s.",
    tip: "Praktisk snarvei: mål bare hvor mye fjæren synker under lasten, ikke $k$ og $m$ hver for seg." },
  en: { t: "Static deflection and frequency",
    intro: "If you know the static deflection $\\delta$ a mass produces on its spring, you can find the natural frequency without knowing $k$ or $m$ separately. This follows because $k\\delta = mg$, which gives $k/m = g/\\delta$ directly in the formula for $\\omega_n$.",
    f: [["\\omega_n = \\sqrt{g/\\delta}", "natural angular frequency from static deflection"]],
    legend: [["\\delta", "static deflection", "m"], ["g", "gravitational acceleration", "m/s²"]],
    ex: "A static deflection of $\\delta = 5$ mm:\n$\\omega_n = \\sqrt{9.81/0.005} \\approx 44.3$ rad/s.",
    tip: "Handy shortcut: just measure how much the spring sags under the load, not $k$ and $m$ separately." } }
]);

// ================= SVING – enhet 1: Demping =================
TOPICS("SVING", 1, [
{ id: "dempingsforhold",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 70H220" class="dim"/><path d="M25 70Q45 25 65 70T105 70T145 70T185 70T220 70" class="d"/><path d="M25 70Q45 25 65 70" class="dash"/><text x="35" y="20">ζ<tspan dy="4" font-size="10">1</tspan></text></svg>`,
  nb: { t: "Dempingsforhold",
    intro: "Demping fjerner energi fra en svingning, for eksempel som varme i en støtdemper. Dempingsforholdet $\\zeta$ sammenligner faktisk demping med kritisk demping. Er $\\zeta < 1$ svinger systemet med avtagende amplitude (underdempet), er $\\zeta = 1$ går det raskest mulig tilbake uten å svinge (kritisk), og er $\\zeta > 1$ går det enda tregere tilbake (overdempet).",
    f: [["\\zeta = c/c_c", "dempingsforhold"], ["c_c = 2\\sqrt{km}", "kritisk dempingskoeffisient"]],
    legend: [["\\zeta", "dempingsforhold", ""], ["c", "dempingskoeffisient", "Ns/m"], ["c_c", "kritisk dempingskoeffisient", "Ns/m"]],
    ex: "$m = 4$ kg, $k = 4000$ N/m, $c = 100$ Ns/m:\n$c_c = 2\\sqrt{4000\\cdot 4} = 400$ Ns/m, så $\\zeta = 100/400 = 0{,}25$ (underdempet).",
    tip: "$\\zeta = 1$ er grensen: raskeste retur til ro uten å svinge forbi likevekten." },
  en: { t: "Damping ratio",
    intro: "Damping removes energy from a vibration, for example as heat in a shock absorber. The damping ratio $\\zeta$ compares the actual damping with the critical damping. If $\\zeta < 1$ the system oscillates with decaying amplitude (underdamped), if $\\zeta = 1$ it returns as fast as possible without oscillating (critical), and if $\\zeta > 1$ it returns even more slowly (overdamped).",
    f: [["\\zeta = c/c_c", "damping ratio"], ["c_c = 2\\sqrt{km}", "critical damping coefficient"]],
    legend: [["\\zeta", "damping ratio", ""], ["c", "damping coefficient", "Ns/m"], ["c_c", "critical damping coefficient", "Ns/m"]],
    ex: "$m = 4$ kg, $k = 4000$ N/m, $c = 100$ Ns/m:\n$c_c = 2\\sqrt{4000\\cdot 4} = 400$ Ns/m, so $\\zeta = 100/400 = 0.25$ (underdamped).",
    tip: "$\\zeta = 1$ is the boundary: the fastest return to rest without overshooting equilibrium." } },
{ id: "dempet-egenfrekvens",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 70H220" class="dim"/><path d="M25 70Q40 30 55 70T85 65T115 70T145 68T175 70T205 69" class="d"/><path d="M25 70Q40 25 55 70T85 70T115 70T145 70T175 70T205 70" class="dash"/></svg>`,
  nb: { t: "Dempet egenfrekvens",
    intro: "Demping senker svingefrekvensen litt sammenlignet med det udempede systemet. For små dempingsforhold, som er vanlig i praksis, er forskjellen liten, men den vokser raskt når $\\zeta$ nærmer seg 1.",
    f: [["\\omega_d = \\omega_n\\sqrt{1-\\zeta^2}", "dempet vinkelfrekvens"]],
    legend: [["\\omega_d", "dempet vinkelfrekvens", "rad/s"], ["\\omega_n", "udempet egen vinkelfrekvens", "rad/s"], ["\\zeta", "dempingsforhold", ""]],
    ex: "$\\omega_n = 20$ rad/s, $\\zeta = 0{,}2$:\n$\\omega_d = 20\\sqrt{1-0{,}04} \\approx 19{,}6$ rad/s.",
    tip: "For $\\zeta < 0{,}2$ er $\\omega_d \\approx \\omega_n$ – forskjellen er ofte til å se bort fra." },
  en: { t: "Damped natural frequency",
    intro: "Damping lowers the oscillation frequency slightly compared with the undamped system. For small damping ratios, common in practice, the difference is small, but it grows quickly as $\\zeta$ approaches 1.",
    f: [["\\omega_d = \\omega_n\\sqrt{1-\\zeta^2}", "damped angular frequency"]],
    legend: [["\\omega_d", "damped angular frequency", "rad/s"], ["\\omega_n", "undamped natural angular frequency", "rad/s"], ["\\zeta", "damping ratio", ""]],
    ex: "$\\omega_n = 20$ rad/s, $\\zeta = 0.2$:\n$\\omega_d = 20\\sqrt{1-0.04} \\approx 19.6$ rad/s.",
    tip: "For $\\zeta < 0.2$, $\\omega_d \\approx \\omega_n$ – the difference is often negligible." } },
{ id: "logaritmisk-dekrement",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 70H220" class="dim"/><path d="M25 70Q45 20 65 70T105 55T145 65T185 69" class="d"/><path d="M65 20V70 M105 40V70" class="dash"/><text x="55" y="15">x<tspan dy="4" font-size="10">1</tspan></text><text x="95" y="36">x<tspan dy="4" font-size="10">2</tspan></text></svg>`,
  nb: { t: "Logaritmisk dekrement",
    intro: "Ved å måle hvor mye amplituden avtar fra én topp til den neste i en fri, dempet svingning, kan du finne dempingsforholdet uten å kjenne $c$, $k$ eller $m$. Det logaritmiske dekrementet $\\delta$ er den naturlige logaritmen av forholdet mellom to påfølgende topper.",
    f: [["\\delta = \\ln(x_1/x_2)", "logaritmisk dekrement"], ["\\zeta \\approx \\delta/(2\\pi)", "tilnærming for små $\\zeta$"]],
    legend: [["\\delta", "logaritmisk dekrement", ""], ["x_1,\\ x_2", "amplitude ved to påfølgende topper", "mm"]],
    ex: "Topper på 20 mm og 12 mm:\n$\\delta = \\ln(20/12) \\approx 0{,}511$, så $\\zeta \\approx 0{,}511/(2\\pi) \\approx 0{,}081$.",
    tip: "Bruk gjerne flere sykluser og del på antallet for å redusere måleusikkerhet." },
  en: { t: "Logarithmic decrement",
    intro: "By measuring how much the amplitude decays from one peak to the next in a free, damped vibration, you can find the damping ratio without knowing $c$, $k$ or $m$. The logarithmic decrement $\\delta$ is the natural logarithm of the ratio between two successive peaks.",
    f: [["\\delta = \\ln(x_1/x_2)", "logarithmic decrement"], ["\\zeta \\approx \\delta/(2\\pi)", "approximation for small $\\zeta$"]],
    legend: [["\\delta", "logarithmic decrement", ""], ["x_1,\\ x_2", "amplitude at two successive peaks", "mm"]],
    ex: "Peaks of 20 mm and 12 mm:\n$\\delta = \\ln(20/12) \\approx 0.511$, so $\\zeta \\approx 0.511/(2\\pi) \\approx 0.081$.",
    tip: "Use several cycles and divide by the count to reduce measurement uncertainty." } }
]);

// ================= SVING – enhet 2: Tvungne svingninger og isolasjon =================
TOPICS("SVING", 2, [
{ id: "resonans-forsterkning",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 120H220" class="dim"/><path d="M20 120V20" class="dim"/><path d="M25.0 93.0 L27.4 93.0 L29.9 92.9 L32.3 92.8 L34.8 92.6 L37.2 92.4 L39.6 92.1 L42.1 91.7 L44.5 91.3 L46.9 90.8 L49.4 90.2 L51.8 89.6 L54.2 88.8 L56.7 87.9 L59.1 86.9 L61.6 85.8 L64.0 84.5 L66.4 83.0 L68.9 81.3 L71.3 79.3 L73.8 77.0 L76.2 74.3 L78.6 71.2 L81.1 67.5 L83.5 63.2 L85.9 58.2 L88.4 52.6 L90.8 46.5 L93.2 40.5 L95.7 35.8 L98.1 33.7 L100.6 35.4 L103.0 40.5 L105.4 47.6 L107.9 55.3 L110.3 62.5 L112.8 68.9 L115.2 74.4 L117.6 79.1 L120.1 83.1 L122.5 86.5 L124.9 89.3 L127.4 91.8 L129.8 94.0 L132.2 95.9 L134.7 97.5 L137.1 99.0 L139.6 100.3 L142.0 101.4 L144.4 102.5 L146.9 103.4 L149.3 104.2 L151.8 105.0 L154.2 105.7 L156.6 106.3 L159.1 106.9 L161.5 107.5 L163.9 108.0 L166.4 108.4 L168.8 108.9 L171.2 109.3 L173.7 109.6 L176.1 110.0 L178.6 110.3 L181.0 110.6 L183.4 110.9 L185.9 111.2 L188.3 111.4 L190.8 111.7 L193.2 111.9 L195.6 112.1 L198.1 112.3 L200.5 112.5 L202.9 112.7 L205.4 112.8 L207.8 113.0 L210.2 113.1 L212.7 113.3 L215.1 113.4 L217.6 113.6 L220.0 113.7" class="d"/><path d="M100 118V26" class="dash"/><text x="104" y="23">r = 1</text></svg>`,
  nb: { t: "Resonans og forsterkning",
    intro: "Når en harmonisk kraft har samme frekvens som systemets egenfrekvens (resonans), blir amplituden mye større enn den statiske utbøyningen $F_0/k$ alene skulle gi. Forsterkningen ved resonans begrenses bare av dempingen: jo mindre demping, desto høyere topp.",
    f: [["X_{res} = \\dfrac{F_0/k}{2\\zeta}", "amplitude ved resonans"]],
    legend: [["X_{res}", "amplitude ved resonans", "m"], ["F_0", "kraftamplitude", "N"], ["\\zeta", "dempingsforhold", ""]],
    ex: "$F_0 = 500$ N, $k = 50$ kN/m, $\\zeta = 0{,}05$:\n$X_{res} = (500/50\\,000)/(2\\cdot 0{,}05) = 0{,}1$ m.",
    tip: "Ved lett demping er forsterkningen ved resonans omtrent $1/(2\\zeta)$ – halver dempingen, dobler du toppen." },
  en: { t: "Resonance and amplification",
    intro: "When a harmonic force has the same frequency as the system's natural frequency (resonance), the amplitude becomes much larger than the static deflection $F_0/k$ alone would give. The amplification at resonance is limited only by the damping: less damping means a higher peak.",
    f: [["X_{res} = \\dfrac{F_0/k}{2\\zeta}", "amplitude at resonance"]],
    legend: [["X_{res}", "amplitude at resonance", "m"], ["F_0", "force amplitude", "N"], ["\\zeta", "damping ratio", ""]],
    ex: "$F_0 = 500$ N, $k = 50$ kN/m, $\\zeta = 0.05$:\n$X_{res} = (500/50\\,000)/(2\\cdot 0.05) = 0.1$ m.",
    tip: "With light damping the amplification at resonance is roughly $1/(2\\zeta)$ – halve the damping, double the peak." } },
{ id: "transmissibilitet",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 115H220" class="dim"/><path d="M20 115V20" class="dim"/><path d="M20 93H220" class="dash"/><path d="M20.0 93.0 L22.2 93.0 L24.4 92.9 L26.6 92.7 L28.8 92.4 L31.0 92.1 L33.2 91.7 L35.4 91.2 L37.6 90.5 L39.8 89.8 L42.0 88.9 L44.2 87.9 L46.4 86.8 L48.6 85.4 L50.8 83.8 L53.0 81.9 L55.2 79.7 L57.4 77.2 L59.6 74.2 L61.8 70.8 L64.0 67.0 L66.2 63.0 L68.4 59.2 L70.6 56.2 L72.8 54.9 L75.0 55.8 L77.2 58.8 L79.4 63.2 L81.6 68.2 L83.8 73.1 L86.0 77.5 L88.2 81.4 L90.4 84.8 L92.6 87.7 L94.8 90.2 L97.0 92.3 L99.2 94.2 L101.4 95.8 L103.6 97.2 L105.8 98.4 L108.0 99.5 L110.2 100.5 L112.4 101.4 L114.6 102.1 L116.8 102.8 L119.0 103.5 L121.2 104.1 L123.4 104.6 L125.6 105.1 L127.8 105.5 L130.0 105.9 L132.2 106.3 L134.4 106.7 L136.6 107.0 L138.8 107.3 L141.0 107.6 L143.2 107.8 L145.4 108.1 L147.6 108.3 L149.8 108.5 L152.0 108.7 L154.2 108.9 L156.4 109.1 L158.6 109.3 L160.8 109.4 L163.0 109.6 L165.2 109.7 L167.4 109.9 L169.6 110.0 L171.8 110.1 L174.0 110.2 L176.2 110.3 L178.4 110.5 L180.6 110.6 L182.8 110.7 L185.0 110.8 L187.2 110.8 L189.4 110.9 L191.6 111.0 L193.8 111.1 L196.0 111.2 L198.2 111.2 L200.4 111.3 L202.6 111.4 L204.8 111.4 L207.0 111.5 L209.2 111.6 L211.4 111.6 L213.6 111.7 L215.8 111.7 L218.0 111.8" class="d"/><path d="M97.8 115V22" class="dash"/><text x="102" y="30">r = √2</text><text x="200" y="88">1</text></svg>`,
  nb: { t: "Transmissibilitet og isolasjon",
    intro: "Transmissibiliteten viser hvor stor andel av en kraft eller vibrasjon som overføres gjennom en fjær-demper-forbindelse (isolator). Under $r = \\sqrt2$ forsterkes kraften faktisk, mens vibrasjonsisolering først virker godt når frekvensforholdet er godt over $\\sqrt2$.",
    f: [["TR = \\dfrac{1}{|1-r^2|}", "transmissibilitet, udempet"], ["r = \\omega/\\omega_n", "frekvensforhold"]],
    legend: [["TR", "transmissibilitet", ""], ["r", "frekvensforhold", ""], ["\\omega", "eksitasjonsfrekvens", "rad/s"]],
    ex: "$r = 3$:\n$TR = 1/|1-9| = 0{,}125$ – bare 12,5 % av kraften overføres.",
    tip: "Myke isolatorer (lav $\\omega_n$) gir høyere $r$ ved driftsfrekvens og dermed bedre isolasjon." },
  en: { t: "Transmissibility and isolation",
    intro: "Transmissibility shows what fraction of a force or vibration is transmitted through a spring-damper mount (isolator). Below $r = \\sqrt2$ the force is actually amplified, while vibration isolation only works well once the frequency ratio is well above $\\sqrt2$.",
    f: [["TR = \\dfrac{1}{|1-r^2|}", "transmissibility, undamped"], ["r = \\omega/\\omega_n", "frequency ratio"]],
    legend: [["TR", "transmissibility", ""], ["r", "frequency ratio", ""], ["\\omega", "excitation frequency", "rad/s"]],
    ex: "$r = 3$:\n$TR = 1/|1-9| = 0.125$ – only 12.5% of the force is transmitted.",
    tip: "Soft mounts (low $\\omega_n$) give a higher $r$ at the operating frequency and thus better isolation." } },
{ id: "ubalansekraft",
  fig: `<svg viewBox="0 0 240 140"><circle cx="120" cy="70" r="40" class="d"/><circle cx="150" cy="50" r="6" class="fill"/><path d="M120 70L150 50" class="dash"/><path d="M150 50L180 30" class="a"/><path d="M180 30l-16 1 8 12z" class="af"/><text x="182" y="28">F</text><text x="105" y="55">e</text></svg>`,
  nb: { t: "Ubalansekraft",
    intro: "En roterende masse som ikke er sentrert på rotasjonsaksen (ubalanse), gir en roterende sentripetalkraft som vokser med kvadratet av vinkelhastigheten. Dette er en vanlig kilde til vibrasjon i motorer, vifter og annet roterende utstyr, og blir raskt et stort problem ved høye turtall.",
    f: [["F = me\\omega^2", "ubalansekraft"]],
    legend: [["F", "ubalansekraft (amplitude)", "N"], ["m", "ubalansemasse", "kg"], ["e", "eksentrisitet", "m"], ["\\omega", "vinkelhastighet", "rad/s"]],
    ex: "$m = 0{,}05$ kg, $e = 5$ mm, $n = 3000$ rpm ($\\omega \\approx 314$ rad/s):\n$F = 0{,}05\\cdot 0{,}005\\cdot 314^2 \\approx 24{,}7$ N.",
    tip: "Fordi $F \\propto \\omega^2$, gir dobbelt turtall fire ganger så stor ubalansekraft." },
  en: { t: "Unbalance force",
    intro: "A rotating mass that is not centered on the rotation axis (unbalance) produces a rotating centripetal force that grows with the square of the angular velocity. This is a common source of vibration in motors, fans and other rotating equipment, and quickly becomes a major problem at high speeds.",
    f: [["F = me\\omega^2", "unbalance force"]],
    legend: [["F", "unbalance force (amplitude)", "N"], ["m", "unbalance mass", "kg"], ["e", "eccentricity", "m"], ["\\omega", "angular velocity", "rad/s"]],
    ex: "$m = 0.05$ kg, $e = 5$ mm, $n = 3000$ rpm ($\\omega \\approx 314$ rad/s):\n$F = 0.05\\cdot 0.005\\cdot 314^2 \\approx 24.7$ N.",
    tip: "Because $F \\propto \\omega^2$, doubling the speed gives four times the unbalance force." } }
]);

// ================= FEM – enhet 0: Stavelementer og stivhetsmatriser =================
TOPICS("FEM", 0, [
{ id: "stivhetsmatrise-stav",
  fig: `<svg viewBox="0 0 240 140"><circle cx="50" cy="70" r="5" class="d"/><path d="M50 70H190" class="b"/><circle cx="190" cy="70" r="5" class="d"/><path d="M50 45H50" class="dim"/><text x="40" y="35">1</text><text x="185" y="35">2</text><text x="90" y="110">EA/L</text></svg>`,
  nb: { t: "Stivhetsmatrise for stavelement",
    intro: "I elementmetoden erstattes en stav med to noder og en stivhetsmatrise som kobler nodeforskyvningene til nodekreftene. For et lineært 1D-stavelement er stivheten $EA/L$, akkurat som i vanlig fjærteori, men skrevet som en $2\\times2$-matrise som virker på begge frihetsgradene.",
    f: [["\\mathbf{k} = \\dfrac{EA}{L}\\begin{pmatrix}1&-1\\\\-1&1\\end{pmatrix}", "elementstivhetsmatrise, 1D stavelement"]],
    legend: [["E", "elastisitetsmodul", "Pa"], ["A", "tverrsnittsareal", "m²"], ["L", "elementlengde", "m"]],
    ex: "$E = 210$ GPa, $A = 100$ mm², $L = 500$ mm:\n$EA/L = 210\\,000\\cdot 100/500 = 42\\,000$ N/mm.",
    tip: "Matrisen alene er singulær – den beskriver bare stivhet, ikke hvor staven er festet." },
  en: { t: "Bar element stiffness matrix",
    intro: "In the finite element method, a bar is replaced by two nodes and a stiffness matrix that links the nodal displacements to the nodal forces. For a linear 1D bar element the stiffness is $EA/L$, just as in ordinary spring theory, but written as a $2\\times2$ matrix that acts on both degrees of freedom.",
    f: [["\\mathbf{k} = \\dfrac{EA}{L}\\begin{pmatrix}1&-1\\\\-1&1\\end{pmatrix}", "element stiffness matrix, 1D bar element"]],
    legend: [["E", "modulus of elasticity", "Pa"], ["A", "cross-sectional area", "m²"], ["L", "element length", "m"]],
    ex: "$E = 210$ GPa, $A = 100$ mm², $L = 500$ mm:\n$EA/L = 210\\,000\\cdot 100/500 = 42\\,000$ N/mm.",
    tip: "The matrix alone is singular – it only describes stiffness, not how the bar is supported." } },
{ id: "assemblering",
  fig: `<svg viewBox="0 0 240 140"><circle cx="40" cy="70" r="5" class="d"/><path d="M40 70H120" class="b"/><circle cx="120" cy="70" r="5" class="d"/><path d="M120 70H200" class="b"/><circle cx="200" cy="70" r="5" class="d"/><text x="30" y="35">1</text><text x="115" y="35">2</text><text x="195" y="35">3</text><text x="65" y="100">k<tspan dy="4" font-size="10">1</tspan></text><text x="150" y="100">k<tspan dy="4" font-size="10">2</tspan></text></svg>`,
  nb: { t: "Assemblering",
    intro: "En konstruksjon settes sammen av flere elementer som deler noder. Assemblering legger elementmatrisene inn i én global stivhetsmatrise, der bidragene fra elementer som deler en node summeres i den tilhørende posisjonen. Resultatet, $K\\vec u = \\vec f$, løses for nodeforskyvningene.",
    f: [["K_{ii} = \\sum_e k_{ii}^{(e)}", "diagonalledd: sum av bidrag fra alle elementer i node $i$"]],
    legend: [["K", "global stivhetsmatrise", "N/m"], ["k^{(e)}", "elementstivhetsmatrise", "N/m"]],
    ex: "To stavelementer med $k_1 = 200$ og $k_2 = 300$ N/mm deler node 2:\n$K_{22} = k_1 + k_2 = 500$ N/mm.",
    tip: "Bare elementer som faktisk deler en node, bidrar til samme rad/kolonne i $K$." },
  en: { t: "Assembly",
    intro: "A structure is built from several elements that share nodes. Assembly places the element matrices into one global stiffness matrix, where contributions from elements sharing a node are summed at that position. The result, $K\\vec u = \\vec f$, is solved for the nodal displacements.",
    f: [["K_{ii} = \\sum_e k_{ii}^{(e)}", "diagonal entry: sum of contributions from all elements at node $i$"]],
    legend: [["K", "global stiffness matrix", "N/m"], ["k^{(e)}", "element stiffness matrix", "N/m"]],
    ex: "Two bar elements with $k_1 = 200$ and $k_2 = 300$ N/mm share node 2:\n$K_{22} = k_1 + k_2 = 500$ N/mm.",
    tip: "Only elements that actually share a node contribute to the same row/column in $K$." } },
{ id: "randbetingelser-ku-f",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 70h20 M60 70h20 M90 70h20" class="dash"/><rect x="30" y="55" width="180" height="30" class="dash"/><path d="M40 55V85 M40 55l-10-10M40 65l-10-10M40 75l-10-10M40 85l-10-10" class="d"/><circle cx="120" cy="70" r="4" class="d"/><path d="M120 70H180" class="a"/><path d="M180 70l-14-6v12z" class="af"/><text x="215" y="75">f</text></svg>`,
  nb: { t: "Randbetingelser og Ku = f",
    intro: "Den globale stivhetsmatrisen er singulær før randbetingelser er satt inn, fordi konstruksjonen ennå kan bevege seg fritt som et stivt legeme. Ved å låse kjente forskyvninger (ofte null) og fjerne de tilhørende linjene, blir systemet løsbart for de resterende, ukjente forskyvningene.",
    f: [["K\\vec u = \\vec f", "det lineære likningssystemet som løses"]],
    legend: [["K", "global stivhetsmatrise (etter randbetingelser)", ""], ["\\vec u", "nodeforskyvninger (ukjente)", "m"], ["\\vec f", "nodekrefter", "N"]],
    ex: "Node 1 låst, kraft $F$ i node 2 av en enkelt stav:\n$u_2 = FL/(EA)$ etter at rad/kolonne 1 er fjernet.",
    tip: "Nok frihetsgrader må låses til å hindre stivlegemebevegelse, ellers forblir $K$ singulær." },
  en: { t: "Boundary conditions and Ku = f",
    intro: "The global stiffness matrix is singular before boundary conditions are applied, because the structure can still move freely as a rigid body. By fixing known displacements (often zero) and removing the corresponding rows, the system becomes solvable for the remaining unknown displacements.",
    f: [["K\\vec u = \\vec f", "the linear system that is solved"]],
    legend: [["K", "global stiffness matrix (after boundary conditions)", ""], ["\\vec u", "nodal displacements (unknown)", "m"], ["\\vec f", "nodal forces", "N"]],
    ex: "Node 1 fixed, force $F$ at node 2 of a single bar:\n$u_2 = FL/(EA)$ after row/column 1 is removed.",
    tip: "Enough degrees of freedom must be fixed to prevent rigid-body motion, or $K$ stays singular." } }
]);

// ================= FEM – enhet 1: Svak form og formfunksjoner =================
TOPICS("FEM", 1, [
{ id: "formfunksjoner",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 110H210" class="dim"/><path d="M30 110V30" class="dim"/><path d="M30 30L210 110" class="a"/><path d="M210 110L30 110" class="d"/><path d="M30 110L210 30" class="t"/><circle cx="30" cy="110" r="3" class="d"/><circle cx="210" cy="110" r="3" class="d"/><text x="15" y="120">1</text><text x="207" y="120">2</text><text x="37" y="53">N<tspan dy="4" font-size="10">1</tspan></text><text x="180" y="45">N<tspan dy="4" font-size="10">2</tspan></text></svg>`,
  nb: { t: "Formfunksjoner",
    intro: "Formfunksjoner beskriver hvordan forskyvningen interpoleres mellom nodeverdiene inni et element. For et lineært element på $[0,1]$ er $N_1$ og $N_2$ rette linjer, hver lik 1 i sin egen node og 0 i den andre. Summen av formfunksjonene er alltid 1, en «partisjon av enheten».",
    f: [["N_1(\\xi) = 1-\\xi,\\quad N_2(\\xi) = \\xi", "lineære formfunksjoner på $[0,1]$"], ["u(\\xi) = N_1u_1 + N_2u_2", "interpolert forskyvning"]],
    legend: [["\\xi", "lokal koordinat", ""], ["N_1,\\ N_2", "formfunksjoner", ""], ["u_1,\\ u_2", "nodeverdier", ""]],
    ex: "$u_1 = 2$, $u_2 = 8$, $\\xi = 0{,}25$:\n$u = 2(1-0{,}25) + 8\\cdot 0{,}25 = 3{,}5$.",
    tip: "Summen $N_1 + N_2 = 1$ overalt – det gjør at elementet kan gjengi en konstant forskyvning." },
  en: { t: "Shape functions",
    intro: "Shape functions describe how displacement is interpolated between the nodal values inside an element. For a linear element on $[0,1]$, $N_1$ and $N_2$ are straight lines, each equal to 1 at its own node and 0 at the other. The sum of the shape functions is always 1, a \"partition of unity\".",
    f: [["N_1(\\xi) = 1-\\xi,\\quad N_2(\\xi) = \\xi", "linear shape functions on $[0,1]$"], ["u(\\xi) = N_1u_1 + N_2u_2", "interpolated displacement"]],
    legend: [["\\xi", "local coordinate", ""], ["N_1,\\ N_2", "shape functions", ""], ["u_1,\\ u_2", "nodal values", ""]],
    ex: "$u_1 = 2$, $u_2 = 8$, $\\xi = 0.25$:\n$u = 2(1-0.25) + 8\\cdot 0.25 = 3.5$.",
    tip: "The sum $N_1 + N_2 = 1$ everywhere – this lets the element reproduce a constant displacement." } },
{ id: "svak-form",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 100H210" class="d"/><path d="M30 100Q80 30 120 100T210 100" class="a"/><text x="115" y="20">w</text><text x="215" y="105">x</text></svg>`,
  nb: { t: "Svak form",
    intro: "Differensiallikninger stiller ofte krav om deriverbarhet som er strengere enn det enkle elementer kan gi. Ved å multiplisere med en testfunksjon $w$ og integrere delvis, flyttes én derivasjon over på testfunksjonen. Det gir svak form, som krever mindre glatthet og passer naturlig med formfunksjonene.",
    f: [["\\int_\\Omega w\\left(-\\dfrac{d}{dx}\\left(k\\dfrac{du}{dx}\\right)\\right)dx = \\int_\\Omega wf\\,dx", "sterk form, før delvis integrasjon"]],
    legend: [["w", "testfunksjon", ""], ["u", "ukjent felt (f.eks. forskyvning)", ""], ["\\Omega", "elementets område", ""]],
    ex: "Delvis integrasjon flytter én derivasjon fra $u$ til $w$,\nslik at bare første deriverte av begge trengs, ikke andre deriverte av $u$.",
    tip: "Svak form er derfor mindre streng enn den opprinnelige (sterke) differensiallikningen." },
  en: { t: "Weak form",
    intro: "Differential equations often demand more smoothness than simple elements can provide. By multiplying with a test function $w$ and integrating by parts, one derivative is shifted onto the test function. This gives the weak form, which requires less smoothness and fits naturally with the shape functions.",
    f: [["\\int_\\Omega w\\left(-\\dfrac{d}{dx}\\left(k\\dfrac{du}{dx}\\right)\\right)dx = \\int_\\Omega wf\\,dx", "strong form, before integrating by parts"]],
    legend: [["w", "test function", ""], ["u", "unknown field (e.g. displacement)", ""], ["\\Omega", "element domain", ""]],
    ex: "Integrating by parts moves one derivative from $u$ to $w$,\nso only first derivatives of both are needed, not second derivatives of $u$.",
    tip: "The weak form is therefore less strict than the original (strong) differential equation." } },
{ id: "gauss-kvadratur",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 110H210" class="dim"/><path d="M30 30Q120 100 210 30" class="d"/><circle cx="80" cy="72" r="4" class="af"/><circle cx="160" cy="72" r="4" class="af"/><text x="53" y="67">ξ<tspan dy="4" font-size="10">1</tspan></text><text x="167" y="60">ξ<tspan dy="4" font-size="10">2</tspan></text></svg>`,
  nb: { t: "Gauss-kvadratur",
    intro: "Elementintegraler regnes sjelden ut analytisk – i stedet brukes numerisk integrasjon i noen få punkter. Gauss-kvadratur velger punktenes plassering og vekter slik at polynomer av lav grad integreres eksakt med svært få punkter, noe som gjør FEM-beregninger raske.",
    f: [["\\int_{-1}^1 g(\\xi)\\,d\\xi \\approx \\sum_i w_ig(\\xi_i)", "numerisk integrasjon med Gauss-punkter"]],
    legend: [["\\xi_i", "Gauss-punkt", ""], ["w_i", "vekt", ""], ["n", "antall punkter", ""]],
    ex: "1 punkt ($\\xi=0$, vekt 2) for $g(\\xi)=3\\xi^2+2\\xi+4$:\ngir $2\\cdot 4 = 8$, mens eksakt verdi er $3\\cdot\\tfrac23+8=10$ – $\\xi^2$-leddet tapes.",
    tip: "$n$ Gauss-punkter integrerer polynomer opp til grad $2n-1$ eksakt." },
  en: { t: "Gauss quadrature",
    intro: "Element integrals are rarely evaluated analytically – instead numerical integration at a few points is used. Gauss quadrature chooses the point locations and weights so that low-degree polynomials are integrated exactly with very few points, which makes FEM computations fast.",
    f: [["\\int_{-1}^1 g(\\xi)\\,d\\xi \\approx \\sum_i w_ig(\\xi_i)", "numerical integration at Gauss points"]],
    legend: [["\\xi_i", "Gauss point", ""], ["w_i", "weight", ""], ["n", "number of points", ""]],
    ex: "1 point ($\\xi=0$, weight 2) for $g(\\xi)=3\\xi^2+2\\xi+4$:\ngives $2\\cdot 4 = 8$, while the exact value is $3\\cdot\\tfrac23+8=10$ – the $\\xi^2$ term is lost.",
    tip: "$n$ Gauss points integrate polynomials up to degree $2n-1$ exactly." } }
]);

// ================= FEM – enhet 2: Elementtyper, mesh og feil =================
TOPICS("FEM", 2, [
{ id: "cst-element",
  fig: `<svg viewBox="0 0 240 140"><path d="M40 110L200 110L120 25Z" class="fill"/><circle cx="40" cy="110" r="3" class="d"/><circle cx="200" cy="110" r="3" class="d"/><circle cx="120" cy="25" r="3" class="d"/><text x="30" y="128">1</text><text x="195" y="128">2</text><text x="117" y="18">3</text></svg>`,
  nb: { t: "CST-elementet",
    intro: "Det enkleste todimensjonale elementet er den lineære trekanten, ofte kalt CST (constant strain triangle). Forskyvningsfeltet inni elementet er lineært, som gjør at tøyningen – og dermed spenningen – blir konstant i hele elementet.",
    f: [["\\varepsilon = \\text{konstant i elementet}", "CST: lineær forskyvning gir konstant tøyning"]],
    legend: [["\\varepsilon", "tøyning", ""]],
    ex: "I et område med stor spenningsgradient (f.eks. ved et hull),\nmå CST-elementer være svært små for å fange variasjonen godt.",
    tip: "Bruk fin mesh eller elementer av høyere orden der spenningen varierer mye – ikke CST alene." },
  en: { t: "The CST element",
    intro: "The simplest two-dimensional element is the linear triangle, often called CST (constant strain triangle). The displacement field inside the element is linear, which makes the strain – and hence the stress – constant throughout the element.",
    f: [["\\varepsilon = \\text{constant in the element}", "CST: linear displacement gives constant strain"]],
    legend: [["\\varepsilon", "strain", ""]],
    ex: "In a region with a steep stress gradient (e.g. near a hole),\nCST elements must be very small to capture the variation well.",
    tip: "Use a fine mesh or higher-order elements where the stress varies a lot – not CST alone." } },
{ id: "mesh-konvergens",
  fig: `<svg viewBox="0 0 240 140"><rect x="30" y="30" width="80" height="80" class="d"/><path d="M70 30V110 M30 70H110" class="d"/><rect x="130" y="30" width="80" height="80" class="d"/><path d="M150 30V110 M170 30V110 M190 30V110 M130 50H210 M130 70H210 M130 90H210" class="d"/></svg>`,
  nb: { t: "Meshforfining og konvergens",
    intro: "FEM-løsningen nærmer seg den eksakte løsningen når elementene gjøres mindre (h-forfining) eller polynomgraden økes (p-forfining). En konvergensstudie sammenligner resultatet ved ulike mesh-tettheter for å sjekke at svaret ikke lenger endrer seg mye.",
    f: [["\\text{Feil} \\propto h^{p+1}", "feil i forskyvning, elementgrad $p$"]],
    legend: [["h", "elementstørrelse", "m"], ["p", "polynomgrad", ""]],
    ex: "Lineære elementer ($p=1$), halvert elementstørrelse:\nfeilen reduseres med en faktor $2^2 = 4$.",
    tip: "Legg de fineste elementene der spenningsgradientene er størst, ikke jevnt over hele modellen." },
  en: { t: "Mesh refinement and convergence",
    intro: "The FEM solution approaches the exact solution as elements are made smaller (h-refinement) or the polynomial degree is raised (p-refinement). A convergence study compares the result at different mesh densities to check that the answer no longer changes much.",
    f: [["\\text{Error} \\propto h^{p+1}", "displacement error, element degree $p$"]],
    legend: [["h", "element size", "m"], ["p", "polynomial degree", ""]],
    ex: "Linear elements ($p=1$), element size halved:\nthe error is reduced by a factor of $2^2 = 4$.",
    tip: "Put the finest elements where the stress gradients are largest, not evenly over the whole model." } },
{ id: "spenningssingularitet",
  fig: `<svg viewBox="0 0 240 140"><path d="M40 30H200V110H40Z" class="fill"/><path d="M40 30L90 70L40 110" class="d"/><circle cx="90" cy="70" r="5" class="d"/><path d="M100 55a25 25 0 0 1 0 30" class="t"/><text x="54" y="70">σ</text></svg>`,
  nb: { t: "Spenningssingularitet",
    intro: "Et matematisk skarpt innvendig hjørne gir en teoretisk uendelig spenning i FEM-modellen: spenningen der vokser i stedet for å konvergere når meshen forfines. Løsningen er å modellere en reell avrundingsradius, som fjerner singulariteten og gir en fysisk riktig, endelig spenning.",
    f: [["\\sigma \\to \\infty \\text{ når } r \\to 0", "singularitet ved et skarpt hjørne"]],
    legend: [["\\sigma", "beregnet spenning ved hjørnet", "Pa"], ["r", "avrundingsradius", "m"]],
    ex: "Modell uten avrunding: $\\sigma$ vokser for hver finere mesh.\nMed en reell radius $r > 0$ konvergerer $\\sigma$ mot en endelig verdi.",
    tip: "Voksende spenning ved finere mesh er et varsel om en singularitet, ikke en reell feil i programmet." },
  en: { t: "Stress singularity",
    intro: "A mathematically sharp internal corner gives a theoretically infinite stress in the FEM model: the stress there grows instead of converging as the mesh is refined. The fix is to model a real fillet radius, which removes the singularity and gives a physically correct, finite stress.",
    f: [["\\sigma \\to \\infty \\text{ as } r \\to 0", "singularity at a sharp corner"]],
    legend: [["\\sigma", "computed stress at the corner", "Pa"], ["r", "fillet radius", "m"]],
    ex: "Model without a fillet: $\\sigma$ grows with every finer mesh.\nWith a real radius $r > 0$, $\\sigma$ converges to a finite value.",
    tip: "Growing stress under mesh refinement is a warning sign of a singularity, not a real software bug." } }
]);
